# El tema SDDM (Main.qml + metadata.desktop) vive en configs/sddm/ — se lee
# con _leer_config() mas abajo, compartido con build-iso.yml (que arma el
# mismo tema, con textos en espanol, para el greeter del live). Antes vivia
# hardcodeado aca ADEMAS de por separado en build-iso.yml -- dos copias que
# ya habian divergido (API distinta, un bug de layout solo en una de las
# dos). Unificado a una sola fuente para que no puedan volver a divergir
# en silencio.
def _ejecutar (cmd :list [str ],timeout :int =30 )->tuple [int ,str ,str ]:
    try :
        r =subprocess .run (cmd ,capture_output =True ,text =True ,timeout =timeout )
        return r .returncode ,r .stdout .strip (),r .stderr .strip ()
    except FileNotFoundError :
        return -1 ,"",f"No encontrado: {cmd [0 ]}"
    except subprocess .TimeoutExpired :
        return -2 ,"","Timeout"
    except Exception as e :
        return -3 ,"",str (e )

def detectar_disco_arranque ()->str :
    rc ,out ,_ =_ejecutar (["findmnt","-n","-o","SOURCE","/"])
    if rc ==0 and out :
        dev =out .strip ()

        if dev .startswith ("/dev/mapper/")or dev .startswith ("/dev/dm-"):
            rc2 ,out2 ,_ =_ejecutar (["lsblk","-no","PKNAME",dev ])
            if rc2 ==0 and out2 .strip ():
                return out2 .strip ().split ()[0 ]
        dev =dev .removeprefix ("/dev/")
        return re .sub (r'p?\d+$','',dev )
    rc ,out ,_ =_ejecutar (["lsblk","-J","-o","NAME,MOUNTPOINTS"])
    if rc ==0 and out :
        try :
            for disco in json .loads (out ).get ("blockdevices",[]):
                if _disco_tiene_mount (disco ,"/"):
                    return disco ["name"]
        except json .JSONDecodeError as e :

            print (f"[WARN] listar_disco_arranque: lsblk JSON inválido: {e }",file =sys .stderr )
    try :
        with open ("/proc/mounts")as f :
            for linea in f :
                partes =linea .split ()
                if len (partes )>=2 and partes [1 ]=="/":
                    src =partes [0 ]
                    if src .startswith ("/dev/mapper/")or src .startswith ("/dev/dm-"):
                        rc2 ,out2 ,_ =_ejecutar (["lsblk","-no","PKNAME",src ])
                        if rc2 ==0 and out2 .strip ():
                            return out2 .strip ().split ()[0 ]
                    return re .sub (r'p?\d+$','',src .removeprefix ("/dev/"))
    except OSError :
        pass
    return ""

def _disco_tiene_mount (nodo :dict ,punto :str )->bool :
    mps =nodo .get ("mountpoints")or [nodo .get ("mountpoint")]
    if punto in (mps or []):
        return True
    for hijo in nodo .get ("children",[]):
        if _disco_tiene_mount (hijo ,punto ):
            return True
    return False

def listar_discos ()->list [dict ]:
    rc ,out ,_ =_ejecutar ([
    "lsblk","-J","-b","-o","NAME,SIZE,TYPE,MOUNTPOINTS,MODEL,TRAN,ROTA,VENDOR"
    ])
    if rc !=0 or not out :
        return []
    try :
        datos =json .loads (out )
    except json .JSONDecodeError :
        return []
    disco_arranque =detectar_disco_arranque ()
    discos =[]
    for nodo in datos .get ("blockdevices",[]):
        if nodo .get ("type")!="disk":
            continue
        nombre =nodo .get ("name","")
        size_b =int (nodo .get ("size")or 0 )
        model =(nodo .get ("model")or nodo .get ("vendor")or "").strip ()
        tran =(nodo .get ("tran")or "").strip ()
        rota =nodo .get ("rota")in ("1",True ,1 )
        parts =[]
        for hijo in nodo .get ("children",[]):
            if hijo .get ("type")in ("part","lvm"):
                mps =hijo .get ("mountpoints")or [hijo .get ("mountpoint")]
                parts .append ({
                "name":hijo .get ("name",""),
                "size_b":int (hijo .get ("size")or 0 ),
                "mounts":[m for m in mps if m ],
                })
        discos .append ({
        "name":nombre ,
        "size_b":size_b ,
        "size_human":_bytes_a_human (size_b ),
        "model":model or "Disco desconocido",
        "tran":tran .upper ()if tran else "—",
        "tipo":"HDD"if rota else "SSD/NVMe",
        "es_arranque":(nombre ==disco_arranque ),
        "particiones":parts ,
        "montajes":_montes_activos (nodo ),
        })
    return discos

def _montes_activos (nodo :dict )->list [str ]:
    result =[]
    mps =nodo .get ("mountpoints")or [nodo .get ("mountpoint")]
    result .extend ([m for m in (mps or [])if m ])
    for hijo in nodo .get ("children",[]):
        result .extend (_montes_activos (hijo ))
    return result

def _bytes_a_human (b :int )->str :
    fb =float (b )
    for unit in ("B","KB","MB","GB","TB"):
        if fb <1024.0 :
            return f"{fb :.1f} {unit }"
        fb /=1024.0
    return f"{fb :.1f} PB"

# GUID oficial de partición EFI System en tablas GPT (UEFI Specification,
# confirmado también en ArchWiki y Microsoft Learn). Es la misma señal que
# usa el propio firmware UEFI para encontrar la ESP — no una heurística de
# tamaño u orden.
_GUID_EFI_SYSTEM_PARTITION ="c12a7328-f81f-11d2-ba4b-00a0c93ec93b"

def detectar_particiones_manual (dev :str ,uefi :bool )->dict :
    """Modo manual: analiza lo que el usuario dejó particionado a mano en
    'dev' (ej. /dev/nvme0n1) y separa la partición EFI/boot de las
    candidatas a root.

    GPT: compara PARTTYPE de cada partición contra el GUID oficial de EFI
    System Partition — señal estructural real, la misma que usa el
    firmware UEFI.

    MBR (sin tabla GPT): usa 'sfdisk -A dev' sin número de partición, que
    lista las particiones con el flag bootable/activo encendido (mismo
    criterio que ya usa 'parted ... set 1 boot on' en el modo automático
    de este instalador). sfdisk detecta solo internamente si el disco es
    GPT y avisa por stderr en vez de fallar, así que no hace falta
    detectar la tabla nosotros mismos antes de llamarlo.

    'uefi' (booleano, viene de es_uefi() del sistema en vivo) decide qué
    SIGNIFICA el flag bootable en MBR: en BIOS Legacy no existe el
    concepto de partición EFI — el flag bootable marca directamente la
    partición que contiene /boot (con frecuencia la única partición del
    disco), así que en ese caso nunca se descarta como "EFI", siempre
    queda como candidata a root. Solo si el firmware es UEFI pero el
    disco resultó estar en MBR (caso inusual, p.ej. "UEFI CSM/legacy
    boot") se sigue tratando el flag bootable como equivalente al GUID
    GPT de ESP, porque en ese caso sí puede haber una partición separada
    pensada para el firmware. Confirmado con ArchWiki/foros: en BIOS/MBR
    "lo que quieres bootable es tu directorio raíz, o /boot si está
    separado" — nunca una partición EFI real, ese concepto no existe sin
    UEFI.

    Devuelve {"efi": "/dev/X" | "", "candidatas_root": [ {"name","size_b",
    "size_human","fstype"} , ... ], "es_gpt": bool}. No decide sola cuál
    partición es root si hay más de una candidata — eso lo resuelve el
    usuario en el dropdown del wizard."""
    rc ,out ,_ =_ejecutar ([
    "lsblk","-J","-b","-n","-o",
    "NAME,SIZE,TYPE,PARTTYPE,FSTYPE,MOUNTPOINTS",dev ,
    ])
    if rc !=0 or not out :
        return {"efi":"","candidatas_root":[],"es_gpt":False }
    try :
        datos =json .loads (out )
    except json .JSONDecodeError :
        return {"efi":"","candidatas_root":[],"es_gpt":False }

    _nodo_disco =next (
    (n for n in datos .get ("blockdevices",[])if n .get ("name")==dev .removeprefix ("/dev/")),
    None ,
    )
    _hijos =(_nodo_disco or {}).get ("children",[])or []
    if not _hijos :
        # fallback: algunas versiones de lsblk aplanan el árbol si se le
        # pasa un device específico en vez del disco completo
        _hijos =datos .get ("blockdevices",[])

    _es_gpt =any ((h .get ("parttype")or "").strip ().lower ()==_GUID_EFI_SYSTEM_PARTITION
    for h in _hijos )

    _efi =""
    _boot_flags :set [str ]=set ()
    if not _es_gpt and uefi :
        # MBR + firmware UEFI (caso inusual: UEFI en modo legacy/CSM):
        # preguntarle a sfdisk qué partición tiene el flag bootable, igual
        # que hace el modo automático de este instalador para marcar la
        # partición equivalente a ESP. En BIOS puro (uefi=False) esta
        # llamada no hace falta — el flag bootable jamás se interpreta
        # como EFI en ese caso, así que no vale la pena el subprocess.
        # 'sfdisk -A dev' sin número de partición = modo listado (confirmado
        # en sfdisk(8)). No falla si el disco resulta ser GPT — solo avisa
        # por stderr y entra en modo PMBR, así que es seguro llamarlo aunque
        # _es_gpt haya dado False por error.
        try :
            _rc_sf ,_out_sf ,_ =_ejecutar (["sfdisk","-A",dev ])
            if _rc_sf ==0 :
                for _line in _out_sf .splitlines ():
                    _line =_line .strip ()
                    if _line .startswith (dev ):
                        _boot_flags .add (_line .split ()[0 ].removeprefix ("/dev/"))
        except Exception :
            pass

    _candidatas :list [dict ]=[]
    for _hijo in _hijos :
        if _hijo .get ("type")!="part":
            continue
        _name =_hijo .get ("name","")
        _parttype =(_hijo .get ("parttype")or "").strip ().lower ()
        _fstype =(_hijo .get ("fstype")or "").strip ()
        _size_b =int (_hijo .get ("size")or 0 )

        _es_esta_efi =(
        (_es_gpt and _parttype ==_GUID_EFI_SYSTEM_PARTITION )
        or (not _es_gpt and uefi and _name in _boot_flags )
        )
        if _es_esta_efi and not _efi :
            _efi ="/dev/"+_name
            continue

        _candidatas .append ({
        "name":"/dev/"+_name ,
        "size_b":_size_b ,
        "size_human":_bytes_a_human (_size_b ),
        "fstype":_fstype or "?",
        })

    return {"efi":_efi ,"candidatas_root":_candidatas ,"es_gpt":_es_gpt }

def detectar_subvolumenes_btrfs (dev_root :str )->list [str ]:
    """Modo manual: si el usuario ya formateó dev_root con Btrfs y creó
    sus propios subvolúmenes, los lista para que el instalador pueda
    saltarse la creación de los que ya existan (según lo acordado) en vez
    de pisarlos.

    No hay forma de inspeccionar subvolúmenes sin montar el filesystem al
    menos una vez (confirmado: 'btrfs subvolume list' opera sobre un punto
    de montaje, no sobre el device crudo) — se monta de solo-lectura
    ('-o ro') para minimizar riesgo, ya que solo se necesita leer."""
    _tmp ="/tmp/btrfs_probe_manual"
    Path (_tmp ).mkdir (parents =True ,exist_ok =True )
    _rc_mnt ,_ ,_ =_ejecutar (["mount","-o","ro",dev_root ,_tmp ])
    if _rc_mnt !=0 :
        try :
            os .rmdir (_tmp )
        except OSError :
            pass
        return []
    try :
        _rc ,_out ,_ =_ejecutar (["btrfs","subvolume","list",_tmp ])
        if _rc !=0 or not _out :
            return []
        _subvols =[]
        for _line in _out .splitlines ():
            # formato: "ID 256 gen 12 top level 5 path @home"
            _m =re .search (r"\bpath\s+(\S+)$",_line .strip ())
            if _m :
                _subvols .append (_m .group (1 ))
        return _subvols
    finally :
        _ejecutar (["umount",_tmp ])
        try :
            os .rmdir (_tmp )
        except OSError :
            pass

def es_uefi ()->bool :
    return Path ("/sys/firmware/efi").exists ()

def detectar_microcode ()->str :
    try :
        with open ("/proc/cpuinfo")as f :
            c =f .read ().lower ()
        if "genuineintel"in c or "intel"in c :
            return "intel-ucode"
        if "authenticamd"in c or "amd"in c :
            return "amd-ucode"
    except OSError :
        pass
    return ""

def verificar_internet ()->bool :

    rc4 ,_ ,_ =_ejecutar (["ping","-c","1","-W","3","8.8.8.8"],timeout =6 )
    if rc4 ==0 :
        return True
    rc6 ,_ ,_ =_ejecutar (["ping6","-c","1","-W","3","2001:4860:4860::8888"],timeout =6 )
    return rc6 ==0

def verificar_herramientas ():
    tools =["parted","mkfs.fat","mkfs.ext4","mkfs.btrfs","btrfs","arch-chroot",
    "pacstrap","genfstab","mount","umount"]
    return {h :shutil .which (h )is not None for h in tools }

