class InstaladorAPI :
    """Métodos expuestos al JavaScript."""

    def __init__ (self ,ventana :"VentanaInstalador"):
        self ._v =ventana

    def set_language (self ,code :str )->bool :
        """Llamado desde JS al elegir idioma. Guarda el código para
        usarlo al generar archivos de configuración (fastfetch, etc.)."""

        allowed =tuple (c for c ,_ in translations .SUPPORTED_LANGS )
        if code in allowed :
            self ._v ._lang =code
            return True
        return False

    def on_ready (self ):
        """DOM listo: poblar discos y mostrar bienvenida."""
        discos =listar_discos ()
        self ._v ._jsc ("pyRenderDiscos",json .dumps (discos ))
        return True

    def iniciar_instalacion (self ,username :str ,password :str ,hostname :str ,
    timezone :str ,disco :str ,bootloader :str ,usb :bool ,
    locale :str ="",keymap :str ="",gaming :bool =False ,
    bore :bool =False ,manual :bool =False ):
        """El usuario pulsó 'Instalar AvalOS' con configuración válida."""
        _username =username .strip ()
        if not _username :

            return False

        if manual and not self ._v ._modo_manual_listo :
            # JS dice modo manual pero Python nunca confirmó una detección
            # válida (verificar_particionado_manual/confirmar_root_manual)
            # — no arrancar _run_instalacion() con dev_efi/dev_root vacíos.
            return False

        self ._v ._username =_username
        self ._v ._password =password
        self ._v ._hostname =hostname .strip ()or DEFAULT_HOSTNAME
        self ._v ._timezone =timezone or DEFAULT_TIMEZONE

        _valid_locales ={lc for lc ,_ in LOCALES }
        self ._v ._locale =locale if locale in _valid_locales else DEFAULT_LOCALE

        _valid_keymaps ={km for km ,_ in KEYMAPS }
        self ._v ._keymap =keymap if keymap in _valid_keymaps else DEFAULT_KEYMAP
        self ._v ._disco_destino =disco
        self ._v ._bootloader =bootloader if bootloader in ('grub','sd-boot','refind','none')else 'grub'
        self ._v ._modo_usb =bool (usb )
        self ._v ._modo_manual =bool (manual )and self ._v ._modo_manual_listo
        self ._v ._install_gaming =bool (gaming )
        self ._v ._install_bore =bool (bore )
        self ._v ._config_lista .set ()
        return True

    def abortar_instalacion (self ):
        self ._v ._abortado =True
        return True

    def abrir_terminal_particionado (self ):
        """Modo manual: lanza una terminal real del live ISO (no dentro
        del webview — webkit2gtk no tiene terminal embebido) para que el
        usuario corra cfdisk/parted/mkfs a mano. Se prueban varios
        emuladores comunes en orden porque este archivo no puede confirmar
        cuál viene empaquetado en el airootfs del ISO (eso se decide en
        build-iso.yml, fuera de este módulo) — así el botón no depende de
        adivinar uno solo y fallar en silencio si no está.
        Bloquea (subprocess.run, no Popen) hasta que el usuario cierre la
        terminal, para que el JS sepa cuándo volver a habilitar el wizard."""
        _candidatos =[
        ["foot"],
        ["kitty"],
        ["alacritty"],
        ["xterm"],
        ["konsole"],
        ["gnome-terminal"],
        ]
        for _cmd in _candidatos :
            if shutil .which (_cmd [0 ]):
                try :
                    subprocess .run (_cmd ,check =False )
                    return True
                except Exception as e :
                    self ._v ._log (self ._v ._t ("log-terminal-launch-warn",term =_cmd [0 ],e =e ),"warn")
                    continue
        self ._v ._log (self ._v ._t ("err-no-terminal-found"),"err")
        return False

    def verificar_particionado_manual (self ,disco :str ):
        """Modo manual: tras volver de la terminal, analiza lo que el
        usuario dejó particionado en 'disco' vía detectar_particiones_manual()
        (GUID GPT / flag bootable MBR — nunca heurística de tamaño u orden).

        Si hay una sola candidata a root y ya tiene Btrfs, además la sondea
        con detectar_subvolumenes_btrfs() para saber si el usuario ya creó
        los subvolúmenes de AvalOS a mano — así _run_instalacion() puede
        saltarse la creación de los que ya existan en vez de pisarlos.

        Si hay más de una candidata a root, NO elige sola — devuelve la
        lista completa para que el wizard se la ofrezca al usuario en un
        dropdown; la decisión final llega después por
        confirmar_root_manual()."""
        _info =detectar_particiones_manual (disco ,es_uefi ())
        _candidatas =_info ["candidatas_root"]

        if not _candidatas :
            self ._v ._modo_manual_listo =False
            return {"ok":False ,"efi":"","candidatas_root":[],"requiere_seleccion":False }

        _subvols_existentes :list [str ]=[]
        if len (_candidatas )==1 and _candidatas [0 ]["fstype"]=="btrfs":
            _subvols_existentes =detectar_subvolumenes_btrfs (_candidatas [0 ]["name"])

        self ._v ._modo_manual_efi =_info ["efi"]
        self ._v ._modo_manual_candidatas =_candidatas
        self ._v ._modo_manual_subvols_existentes =_subvols_existentes
        # Solo queda "listo" sin intervención extra si hay una única
        # candidata — con varias, el wizard debe esperar a
        # confirmar_root_manual() antes de dejar avanzar el botón Instalar.
        self ._v ._modo_manual_listo =(len (_candidatas )==1 )
        if len (_candidatas )==1 :
            self ._v ._modo_manual_root =_candidatas [0 ]["name"]

        return {
        "ok":True ,
        "efi":_info ["efi"],
        "candidatas_root":_candidatas ,
        "requiere_seleccion":len (_candidatas )>1 ,
        "subvols_existentes":_subvols_existentes ,
        }

    def confirmar_root_manual (self ,disco :str ,root_elegida :str ):
        """Modo manual: cuando verificar_particionado_manual() devolvió
        más de una candidata a root, el usuario elige una en el dropdown
        del wizard y esta llamada la fija como definitiva. Vuelve a validar
        contra self._v._modo_manual_candidatas (no confía ciegamente en el
        string que llega de JS) para no aceptar un device arbitrario."""
        _validas ={c ["name"]for c in self ._v ._modo_manual_candidatas }
        if root_elegida not in _validas :
            return False
        self ._v ._modo_manual_root =root_elegida
        # Solo re-sondear subvolúmenes si la elección es btrfs y no se hizo
        # ya en verificar_particionado_manual() (caso de candidata única).
        _cand =next ((c for c in self ._v ._modo_manual_candidatas if c ["name"]==root_elegida ),None )
        if _cand and _cand ["fstype"]=="btrfs"and not self ._v ._modo_manual_subvols_existentes :
            self ._v ._modo_manual_subvols_existentes =detectar_subvolumenes_btrfs (root_elegida )
        self ._v ._modo_manual_listo =True
        return True

    def reintentar (self ):

        with self ._v ._lock :
            if self ._v ._instalando :
                return True
            self ._v ._abortado =False
            self ._v ._instalando =True
        t =threading .Thread (target =self ._v ._run_instalacion ,daemon =True )
        t .start ()
        return True

    def elegir_mirror (self ,choice ):
        # Recibe el clic de uno de los 3 botones del dialog ov-mirror y
        # libera el Event que el hilo de instalación está esperando
        # (bloqueado en _mirror_choice_event.wait() dentro de _run_instalacion).
        self ._v ._mirror_choice =choice
        self ._v ._mirror_choice_event .set ()
        return True

    def reiniciar_equipo (self ):
        try :
            subprocess .Popen (["systemctl","reboot"])
        except Exception as e :
            self ._v ._log (self ._t ("log-reboot-warn",e =e ),"warn")
        return True

    def cerrar (self ):
        if self ._v .window :
            try :
                self ._v .window .destroy ()
            except Exception :
                pass
        return True

class VentanaInstalador :

    def __init__ (self ):
        self .window :"webview.Window | None"=None
        self ._cerrado =False
        self ._abortado =False
        self ._instalando =False
        self ._thread_started =False

        self ._lang ="en"
        self ._username =""
        self ._password =""
        self ._hostname =DEFAULT_HOSTNAME
        self ._timezone =DEFAULT_TIMEZONE
        self ._locale =DEFAULT_LOCALE
        self ._keymap =DEFAULT_KEYMAP
        self ._disco_destino :str |None =None
        self ._bootloader ='grub'
        self ._install_gaming =False
        self ._install_bore =False
        self ._modo_usb =False
        self ._modo_manual =False
        self ._modo_manual_listo =False
        self ._modo_manual_efi =""
        self ._modo_manual_root =""
        self ._modo_manual_candidatas :list [dict ]=[]
        self ._modo_manual_subvols_existentes :list [str ]=[]
        self ._config_lista =threading .Event ()
        self ._mirror_choice_event =threading .Event ()
        self ._mirror_choice :str |None =None
        self ._lock =threading .Lock ()

    def _js (self ,code :str ):
        if self .window and not self ._cerrado :
            try :
                self .window .evaluate_js (code )
            except Exception as e :
                print (f"[JS] {e }")

    def _jsc (self ,func :str ,*args ):
        encoded =", ".join (json .dumps (a ,ensure_ascii =False )for a in args )
        self ._js (f"{func }({encoded })")

    def _log (self ,txt :str ,cls :str ="info"):self ._jsc ("pyLog",txt ,cls )
    def _step (self ,id_ :str ,st :str ,det :str =""):self ._jsc ("pyStep",id_ ,st ,det )
    def _progress (self ,pct :int ):self ._jsc ("pyProgress",pct )
    def _info (self ,id_ :str ,v :str ,c :str =""):self ._jsc ("pyInfo",id_ ,v ,c )
    def _status (self ,msg :str ):self ._jsc ("pyStatus",msg )
    def _label (self ,txt :str ):self ._jsc ("pyStatusLabel",txt )

    def _t (self ,key :str ,**kwargs )->str :
        """Traduce 'key' al idioma elegido por el usuario (self._lang) y
        aplica .format(**kwargs) para los textos con partes dinámicas
        (rutas, nombres de disco, mensajes de excepción, etc. — esas partes
        NUNCA se traducen, solo el texto que las rodea).
        Fallback en cadena: idioma actual → inglés → la propia key (nunca
        debe explotar el log de instalación por una clave faltante)."""
        _tr =translations .TRANSLATIONS .get (self ._lang ,translations .TRANSLATIONS ["en"])
        plantilla =_tr .get (key )or translations .TRANSLATIONS ["en"].get (key )or key
        try :
            return plantilla .format (**kwargs )
        except Exception :

            return plantilla

    def _on_close (self ):
        self ._cerrado =True
        self ._abortado =True
        self ._config_lista .set ()

    def _run_cmd (self ,cmd :list [str ],timeout :int =300 ,
    log_cls :str ="info",
    pre_mkdir :str |None =None )->tuple [int ,str ]:
        if pre_mkdir :
            Path (pre_mkdir ).mkdir (parents =True ,exist_ok =True )
        self ._log (f"$ {' '.join (cmd )}","cmd")
        salida :list [str ]=[]
        proc :"subprocess.Popen[str] | None"=None
        _timed_out =False

        def _kill_on_timeout ():
            nonlocal _timed_out
            _timed_out =True
            if proc is not None :
                try :
                    proc .kill ()
                except Exception :
                    pass

        try :
            proc =subprocess .Popen (cmd ,stdout =subprocess .PIPE ,
            stderr =subprocess .STDOUT ,text =True ,bufsize =1 )
            if proc .stdout is None :
                return -1 ,"No stdout"

            timer =threading .Timer (timeout ,_kill_on_timeout )
            timer .start ()
            try :
                for linea in proc .stdout :
                    linea =linea .rstrip ('\n')
                    if linea :
                        self ._log (linea ,log_cls )
                        salida .append (linea )
                    if self ._abortado :
                        proc .kill ()
                        proc .wait ()
                        return -99 ,"\n".join (salida )
                proc .wait (timeout =5 )
            finally :
                timer .cancel ()

            if _timed_out :
                self ._log (self ._t ("log-timeout-proc",timeout =timeout ),"err")
                return -2 ,"\n".join (salida )

            return proc .returncode ,"\n".join (salida )
        except Exception as e :
            self ._log (self ._t ("log-exception",e =e ),"err")
            if proc is not None :
                try :
                    proc .kill ();proc .wait ()
                except Exception :
                    pass
            return -3 ,""

    @staticmethod
    def _salida_indica_error_gpg (salida :str )->bool :
        """Detecta si la salida de pacman apunta a un problema de confianza/firma GPG
        (clave no confiable, firma inválida, keyring corrupto) en vez de un simple
        problema de conectividad."""
        if not salida :
            return False
        _s =salida .lower ()
        _marcadores =(
        "unknown trust","signature from","invalid or corrupted",
        "keyring is not writable","key could not be looked up",
        "pgp signature",
        )
        return any (m in _s for m in _marcadores )

    def _run_chroot (self ,cmd :list [str ],timeout :int =300 )->tuple [int ,str ]:
        return self ._run_cmd (["arch-chroot",str (MOUNT_ROOT )]+cmd ,timeout =timeout )

    def _run_chroot_stdin (self ,stdin_data :str ,cmd :list [str ],timeout :int =60 )->tuple [int ,str ]:
        """Ejecuta un comando en chroot pasando datos sensibles por stdin (ej: chpasswd)."""
        full_cmd =["arch-chroot",str (MOUNT_ROOT )]+cmd
        try :
            proc =subprocess .run (
            full_cmd ,
            input =stdin_data ,
            capture_output =True ,
            text =True ,
            timeout =timeout ,
            )
            out =(proc .stdout or "")+(proc .stderr or "")
            return proc .returncode ,out .strip ()
        except subprocess .TimeoutExpired :
            self ._log (self ._t ("log-timeout-cmd",timeout =timeout ,cmd0 =cmd [0 ]),"err")
            return -2 ,""
        except Exception as e :
            self ._log (self ._t ("log-exception",e =e ),"err")
            return -3 ,""

    def _limpiar_montajes (self ):
        self ._log (self ._t ("log-cleaning-mounts"),"warn")
        puntos =[

        str (MOUNT_EFI ),
        str (MOUNT_ROOT /"boot"),

        str (MOUNT_ROOT /"proc"),
        str (MOUNT_ROOT /"sys"/"firmware"/"efi"/"efivars"),
        str (MOUNT_ROOT /"sys"),
        str (MOUNT_ROOT /"dev"/"pts"),
        str (MOUNT_ROOT /"dev"),
        str (MOUNT_ROOT /"run"),

        str (MOUNT_ROOT /"tmp"),
        str (MOUNT_ROOT /"var"/"cache"),
        str (MOUNT_ROOT /"var"/"log"),
        str (MOUNT_ROOT /".snapshots"),
        str (MOUNT_ROOT /"home"),

        str (MOUNT_ROOT ),
        str (MOUNT_ISO ),
        ]
        for p in puntos :
            if Path (p ).is_mount ():
                rc ,_ =self ._run_cmd (["umount","-l",p ])
                if rc ==0 :
                    self ._log (self ._t ("log-unmounted",p =p ),"ok")

    def _escribir (self ,ruta_relativa :str ,contenido :str ):
        dest =MOUNT_ROOT /ruta_relativa .lstrip ("/")
        dest .parent .mkdir (parents =True ,exist_ok =True )
        dest .write_text (contenido ,encoding ="utf-8")
        self ._log (self ._t ("log-written",ruta =ruta_relativa ),"ok")

    def _chown_r (self ,ruta :str ,usuario :str ):
        self ._run_chroot (["chown","-R",f"{usuario }:{usuario }",ruta ])

    def _configurar_optimizaciones (self ,gpu_info :dict ,cpu_arch :str ,disco_tipo :str ):
        """Configura ZRAM+zstd, systemd-oomd, BBR, IO scheduler, sysctl y binarios de sistema."""

        self ._log (self ._t ("log-section-optimizations"),"step")

        _bin_dir =MOUNT_ROOT /"usr/local/bin"
        _bin_dir .mkdir (parents =True ,exist_ok =True )
        _gpu_env_bin =_bin_dir /"avalos-gpu-env"
        _gpu_env_bin .write_text (
        "#!/bin/bash\n"
        "# AvalOS: detecta GPU y actualiza el bloque hl.env(...) de hyprland.lua\n"
        "# para cada usuario, entre los marcadores AVALOS_GPU_ENV_START/END.\n"
        "set -uo pipefail\n\n"
        "if lspci 2>/dev/null | grep -qiE 'amd|radeon|amdgpu'; then\n"
        "    GPU_BLOCK='hl.env(\"AMD_VULKAN_ICD\",    \"RADV\")\n"
        "hl.env(\"VDPAU_DRIVER\",      \"radeonsi\")\n"
        "hl.env(\"LIBVA_DRIVER_NAME\", \"radeonsi\")'\n"
        "elif lspci 2>/dev/null | grep -qiE 'intel.*(graphics|vga|display)'; then\n"
        "    GPU_BLOCK='hl.env(\"LIBVA_DRIVER_NAME\", \"iHD\")\n"
        "hl.env(\"VDPAU_DRIVER\",      \"va_gl\")'\n"
        "else\n"
        "    # GPU desconocida: no tocar hyprland.lua, dejar el bloque existente.\n"
        "    exit 0\n"
        "fi\n\n"
        "for hypr_conf in /home/*/.config/hypr/hyprland.lua; do\n"
        "    [[ -f \"$hypr_conf\" ]] || continue\n"
        "    if ! grep -q 'AVALOS_GPU_ENV_START' \"$hypr_conf\"; then\n"
        "        # Marcadores no presentes (instalación antigua o editados por\n"
        "        # el usuario) — no reemplazar a ciegas, evitar corromper el archivo.\n"
        "        continue\n"
        "    fi\n"
        "    tmp=\"$(mktemp)\"\n"
        "    awk -v block=\"$GPU_BLOCK\" '\n"
        "        /-- AVALOS_GPU_ENV_START/ { print; print block; skip=1; next }\n"
        "        /-- AVALOS_GPU_ENV_END/   { skip=0; print; next }\n"
        "        skip { next }\n"
        "        { print }\n"
        "    ' \"$hypr_conf\" > \"$tmp\" && mv \"$tmp\" \"$hypr_conf\"\n"
        "    owner=\"$(stat -c '%U:%G' \"$hypr_conf\")\"\n"
        "    chown \"$owner\" \"$hypr_conf\"\n"
        "done\n"
        )
        _gpu_env_bin .chmod (0o755 )
        self ._log (self ._t ("log-gpu-env-installed"),"ok")

        self ._log (self ._t ("log-installing-scripts"),"info")
        for _script_name in ("avalos-settings","avalos-wallpaper","avalos-about"):
            _contenido =_leer_config (f"scripts/{_script_name }")
            if _contenido :
                _script_path =_bin_dir /_script_name
                _script_path .write_text (_contenido ,encoding ="utf-8")
                _script_path .chmod (0o755 )
                self ._log (self ._t ("log-script-installed",script =_script_name ),"ok")
            else :
                self ._log (self ._t ("log-script-missing",script =_script_name ),"warn")

        _apps_dir =MOUNT_ROOT /"usr"/"share"/"applications"
        _apps_dir .mkdir (parents =True ,exist_ok =True )
        _contenido =_leer_config ("scripts/avalos-settings.desktop")
        if _contenido :
            (_apps_dir /"avalos-settings.desktop").write_text (_contenido ,encoding ="utf-8")
            self ._log (self ._t ("log-settings-desktop-installed"),"ok")
        else :
            self ._log (self ._t ("log-settings-desktop-missing"),"warn")

        (MOUNT_ROOT /"etc"/"avalos-install-date").write_text (
        datetime .datetime .now ().strftime ("%Y-%m-%d %H:%M"),
        encoding ="utf-8"
        )

        zram_path =MOUNT_ROOT /"etc"/"systemd"/"zram-generator.conf"
        zram_path .parent .mkdir (parents =True ,exist_ok =True )
        zram_path .write_text (
        "[zram0]\n"
        "# ZRAM: swap comprimido en RAM — AvalOS\n"
        "# Limita a min(RAM_total/2, 8GB) — estándar zram-generator\n"
        "zram-size = min(ram / 2, 8192)\n"
        "compression-algorithm = zstd\n"
        "swap-priority = 100\n"
        )
        self ._log (self ._t ("log-zram-ok"),"ok")

        oomd_conf =MOUNT_ROOT /"etc"/"systemd"/"oomd.conf"
        oomd_conf .write_text (
        "[OOM]\n"
        "# Mata procesos cuando la presión de swap supera el 85%\n"
        "SwapUsedLimit=85%\n"
        "# o cuando la presión de memoria supera el 70% por más de 10s\n"
        "DefaultMemoryPressureLimit=70%\n"
        "DefaultMemoryPressureDurationSec=10s\n"
        )
        self ._run_chroot (["systemctl","enable","systemd-oomd"])
        self ._log (self ._t ("log-oomd-ok"),"ok")

        sysctl_dir =MOUNT_ROOT /"etc"/"sysctl.d"
        sysctl_dir .mkdir (parents =True ,exist_ok =True )

        (sysctl_dir /"80-avalos-memory.conf").write_text (
        "# AvalOS: memory tuning (conservador, medido)\n"
        "# Reduce agresividad de swap (ZRAM lo maneja)\n"
        "vm.swappiness = 10\n"
        "# Cache de VFS: más agresivo en retener inodos/dentries\n"
        "vm.vfs_cache_pressure = 50\n"
        "# Dirty pages: escribir antes de que sea urgente\n"
        "vm.dirty_ratio = 10\n"
        "vm.dirty_background_ratio = 5\n"
        "# Tiempo máximo de dirty pages antes de flush\n"
        "vm.dirty_expire_centisecs = 3000\n"
        "vm.dirty_writeback_centisecs = 500\n"
        )
        self ._log (self ._t ("log-sysctl-mem-ok"),"ok")

        (sysctl_dir /"81-avalos-bbr.conf").write_text (
        "# AvalOS: BBR congestion control (mainline desde Linux 4.9, muy estable)\n"
        "# FQ como qdisc (requerido por BBR)\n"
        "net.core.default_qdisc = fq\n"
        "# BBR: mejor throughput y latencia que CUBIC\n"
        "net.ipv4.tcp_congestion_control = bbr\n"
        "# Buffers de red razonables\n"
        "net.core.rmem_max = 16777216\n"
        "net.core.wmem_max = 16777216\n"
        "net.ipv4.tcp_rmem = 4096 87380 16777216\n"
        "net.ipv4.tcp_wmem = 4096 65536 16777216\n"
        )
        self ._log ("  BBR: net.ipv4.tcp_congestion_control=bbr + fq","ok")

        (sysctl_dir /"82-avalos-security.conf").write_text (
        "# AvalOS: seguridad mínima razonable\n"
        "kernel.dmesg_restrict = 1\n"
        "kernel.kptr_restrict = 1\n"
        "net.ipv4.conf.default.rp_filter = 1\n"
        "net.ipv4.conf.all.rp_filter = 1\n"
        )
        self ._log (self ._t ("log-sysctl-security-ok"),"ok")

        udev_dir =MOUNT_ROOT /"etc"/"udev"/"rules.d"
        udev_dir .mkdir (parents =True ,exist_ok =True )
        (udev_dir /"60-avalos-iosched.rules").write_text (
        '# AvalOS: IO scheduler automático por tipo de disco\n'
        '# HDD → bfq  (justo, buena latencia interactiva)\n'
        'ACTION=="add|change", KERNEL=="sd[a-z]*", '
        'ATTR{queue/rotational}=="1", ATTR{queue/scheduler}="bfq"\n'
        '# SSD SATA → mq-deadline  (simple, baja latencia)\n'
        'ACTION=="add|change", KERNEL=="sd[a-z]*", '
        'ATTR{queue/rotational}=="0", ATTR{queue/scheduler}="mq-deadline"\n'
        '# NVMe → kyber  (diseñado para baja latencia NVMe)\n'
        'ACTION=="add|change", KERNEL=="nvme[0-9n]*", '
        'ATTR{queue/scheduler}="kyber"\n'
        '# eMMC → mq-deadline\n'
        'ACTION=="add|change", KERNEL=="mmcblk[0-9]*", '
        'ATTR{queue/scheduler}="mq-deadline"\n'
        )
        self ._log (self ._t ("log-io-scheduler",disco_tipo =disco_tipo ),"ok")

        resolved_conf =MOUNT_ROOT /"etc"/"systemd"/"resolved.conf"
        resolved_conf .write_text (
        "[Resolve]\n"
        "# AvalOS: DNS-over-TLS con Cloudflare + Google\n"
        "DNS=1.1.1.1#cloudflare-dns.com 1.0.0.1#cloudflare-dns.com "
        "8.8.8.8#dns.google 8.8.4.4#dns.google\n"
        "FallbackDNS=9.9.9.9#dns.quad9.net\n"
        "DNSOverTLS=yes\n"
        "DNSSEC=allow-downgrade\n"
        "Cache=yes\n"
        "DNSStubListener=yes\n"
        )

        try :
            (MOUNT_ROOT /"etc"/"resolv.conf").unlink (missing_ok =True )
            (MOUNT_ROOT /"etc"/"resolv.conf").symlink_to (
            "../run/systemd/resolve/stub-resolv.conf"
            )
        except OSError as e :

            self ._log (self ._t ("log-resolvconf-fail",e =e ),"warn")
        self ._run_chroot (["systemctl","enable","systemd-resolved"])
        self ._log ("  DNS-over-TLS: systemd-resolved (Cloudflare + Google + Quad9)","ok")

        self ._log (
        self ._t ("log-summary-cpu-gpu-disk",cpu_arch =cpu_arch ,gpu_vendor =gpu_info ["vendor"].upper (),gpu_model =gpu_info ["model"],disco_tipo =disco_tipo .upper ()),
        "ok"
        )

    def _configurar_hyprland (self ,usuario :str ,gpu_info :dict ):
        home =f"home/{usuario }"

        _gpu_vendor =gpu_info .get ("vendor","amd")
        if _gpu_vendor =="intel":
            _gpu_env ="LIBVA_DRIVER_NAME=iHD\nVDPAU_DRIVER=va_gl\n"
        else :
            _gpu_env ="VDPAU_DRIVER=radeonsi\nLIBVA_DRIVER_NAME=radeonsi\n"

        self ._escribir ("etc/environment",f"""\
# BUG-8 FIX: separador ':' en vez de ';' en QT_QPA_PLATFORM.
# Qt parsea esta variable como lista separada por ';' (no ':') de plugins
# de plataforma a probar en orden, con fallback al siguiente si el primero
# no carga. Con ':', Qt busca un plugin llamado literalmente "wayland:xcb",
# no lo encuentra, y cae a su comportamiento por defecto — rompiendo el
# fallback wayland→xcb para toda app Qt que lea /etc/environment (vía PAM/
# systemd), aunque hl.env() en hyprland.lua sí lo tenga bien con ';'.
QT_QPA_PLATFORM=wayland;xcb
QT_AUTO_SCREEN_SCALE_FACTOR=1
QT_WAYLAND_DISABLE_WINDOWDECORATION=1
GDK_BACKEND=wayland,x11
SDL_VIDEODRIVER=wayland
CLUTTER_BACKEND=wayland
MOZ_ENABLE_WAYLAND=1
ELECTRON_OZONE_PLATFORM_HINT=auto
XDG_SESSION_TYPE=wayland
XDG_SESSION_DESKTOP=Hyprland
XDG_CURRENT_DESKTOP=Hyprland
{_gpu_env }__GLX_VENDOR_LIBRARY_NAME=mesa
""")

        self ._escribir ("etc/os-release",f"""\
NAME="AvalOS"
PRETTY_NAME="AvalOS"
ID=avalos
ID_LIKE=arch
BUILD_ID=rolling
ANSI_COLOR="38;2;122;162;247"
HOME_URL="https://github.com/{AVALOS_REPO }"
DOCUMENTATION_URL="https://wiki.archlinux.org"
LOGO=avalos-logo
""")
        self ._escribir ("etc/lsb-release","""\
LSB_VERSION=1.4
DISTRIB_ID=AvalOS
DISTRIB_RELEASE=rolling
DISTRIB_CODENAME=avalos
DISTRIB_DESCRIPTION="AvalOS"
""")

        avalos_repo =(
        "\n[avalos]\n"

        "SigLevel = Required DatabaseOptional\n"
        f"Server = {AVALOS_REPO_URL }\n"
        )

        multilib_repo ="\n[multilib]\nInclude = /etc/pacman.d/mirrorlist\n"

        pac_path =MOUNT_ROOT /"etc"/"pacman.conf"
        try :
            existing =pac_path .read_text (encoding ="utf-8")if pac_path .exists ()else ""
            to_append =""
            if "[avalos]"not in existing :

                _fp ="60FD7887C1DA5B080281B9B8F548844B24E0379D"
                _tmp =MOUNT_ROOT /"tmp"/"avalos.gpg"
                _rc ,_ =self ._run_cmd ([
                "bash","-c",
                f"gpg --homedir /etc/pacman.d/gnupg --armor --export {_fp } > {_tmp } 2>/dev/null"
                ])
                if _rc ==0 and _tmp .stat ().st_size >0 :
                    self ._run_chroot (["pacman-key","--init"])
                    self ._run_chroot (["pacman-key","--add",f"/tmp/avalos.gpg"])
                    self ._run_chroot (["pacman-key","--lsign-key",_fp ])
                    self ._log (f"  clave GPG AvalOS ({_fp }) importada al keyring","ok")
                else :
                    self ._log ("  [WARN] no se pudo exportar la clave GPG de AvalOS desde el live ISO","warn")
                _tmp .unlink (missing_ok =True )
                to_append +=avalos_repo
            if "[multilib]"not in existing :

                existing_new =re .sub (
                r'#\s*\[multilib\]\s*\n#\s*Include\s*=\s*/etc/pacman\.d/mirrorlist',
                "[multilib]\nInclude = /etc/pacman.d/mirrorlist",
                existing
                )
                if "[multilib]"not in existing_new :

                    to_append +=multilib_repo
                else :
                    existing =existing_new
            if to_append :
                pac_path .write_text (existing +to_append ,encoding ="utf-8")
            self ._log ("  repos [avalos] + [multilib] → pacman.conf","ok")
        except OSError as e :
            self ._log (f"[WARN] pacman.conf: {e }","warn")

        _gpu_env_amd =('hl.env("AMD_VULKAN_ICD",    "RADV")\n'
        'hl.env("VDPAU_DRIVER",      "radeonsi")\n'
        'hl.env("LIBVA_DRIVER_NAME", "radeonsi")')
        _gpu_env_intel =('hl.env("LIBVA_DRIVER_NAME", "iHD")\n'
        'hl.env("VDPAU_DRIVER",      "va_gl")')
        _gpu_env_body =_gpu_env_amd if _gpu_vendor =="amd"else _gpu_env_intel
        _gpu_env_str =(
        "-- AVALOS_GPU_ENV_START\n"
        f"{_gpu_env_body }\n"
        "-- AVALOS_GPU_ENV_END"
        )

        _hypr_tmpl =_leer_config ("hyprland/hyprland_conf_lua.template")
        if _hypr_tmpl :
            self ._escribir (f"{home }/.config/hypr/hyprland.lua",
            _hypr_tmpl .replace ("%%GPU_ENV%%",_gpu_env_str )
            .replace ("%%KEYMAP%%",_VCONSOLE_TO_XKB .get (self ._keymap ,self ._keymap )))
        else :

            self ._log (self ._t ("log-hyprland-template-missing"),"err")
            raise RuntimeError (
            "hyprland_conf_lua.template no encontrado en /usr/share/avalos/configs/hyprland/.\n"
            "La imagen ISO está incompleta — reconstruye con build-iso.yml."
            )

        _contenido =_leer_config ("hyprland/hyprpaper.conf")
        if _contenido :
            self ._escribir (f"{home }/.config/hypr/hyprpaper.conf",_contenido )
        else :

            self ._escribir (f"{home }/.config/hypr/hyprpaper.conf",
            "wallpaper {\n    monitor =\n"
            "    path = ~/.config/hypr/wallpaper.png\n"
            "    fit_mode = cover\n}\nsplash = false\nipc = on\n")

        wp_path =MOUNT_ROOT /f"{home }/.config/hypr/wallpaper.png"
        _default_wp =Path ("/usr/share/avalos/wallpaper-default.png")
        try :
            if _default_wp .is_file ():
                wp_path .write_bytes (_default_wp .read_bytes ())
                self ._log (self ._t ("log-wallpaper-copied"),"ok")
            else :
                import struct as _struct ,zlib as _zlib
                def _make_chunk (tag ,data ):
                    crc =_zlib .crc32 (tag +data )&0xffffffff
                    return _struct .pack ('>I',len (data ))+tag +data +_struct .pack ('>I',crc )
                _w ,_h ,_R ,_G ,_B =1920 ,1080 ,26 ,27 ,38
                _rows =(b'\x00'+bytes ([_R ,_G ,_B ])*_w )*_h
                _png =(
                b'\x89PNG\r\n\x1a\n'
                +_make_chunk (b'IHDR',_struct .pack ('>IIBBBBB',_w ,_h ,8 ,2 ,0 ,0 ,0 ))
                +_make_chunk (b'IDAT',_zlib .compress (_rows ,9 ))
                +_make_chunk (b'IEND',b'')
                )
                wp_path .write_bytes (_png )
                self ._log (self ._t ("log-wallpaper-fallback"),"warn")
        except Exception as _e :
            self ._log (f"  [WARN] wallpaper: {_e }","warn")

        _contenido =_leer_config ("hyprland/hypridle.conf")
        if _contenido :
            self ._escribir (f"{home }/.config/hypr/hypridle.conf",_contenido )
        else :
            self ._log (self ._t ("log-hypridle-missing"),"warn")

        _contenido =_leer_config ("hyprland/hyprlock.conf")
        if _contenido :
            self ._escribir (f"{home }/.config/hypr/hyprlock.conf",_contenido )
        else :
            self ._log (self ._t ("log-hyprlock-missing"),"warn")

        _contenido =_leer_config ("waybar/config.jsonc")
        if _contenido :
            self ._escribir (f"{home }/.config/waybar/config.jsonc",_contenido )
        else :
            self ._log (self ._t ("log-waybar-config-missing"),"warn")

        _contenido =_leer_config ("waybar/style.css")
        if _contenido :
            self ._escribir (f"{home }/.config/waybar/style.css",_contenido )
        else :
            self ._log (self ._t ("log-waybar-style-missing"),"warn")

        _contenido =_leer_config ("mako/config")
        if _contenido :
            self ._escribir (f"{home }/.config/mako/config",_contenido )

        _contenido =_leer_config ("rofi/config.rasi")
        if _contenido :
            self ._escribir (f"{home }/.config/rofi/config.rasi",_contenido )

        _contenido =_leer_config ("rofi/powermenu.sh")
        if _contenido :
            self ._escribir (f"{home }/.config/rofi/scripts/powermenu.sh",_contenido )
        try :
            (MOUNT_ROOT /f"{home }/.config/rofi/scripts/powermenu.sh").chmod (0o755 )
        except OSError as e :

            self ._log (self ._t ("log-chmod-powermenu-fail",e =e ),"warn")

        _contenido =_leer_config ("kitty/kitty.conf")
        if _contenido :
            self ._escribir (f"{home }/.config/kitty/kitty.conf",_contenido )

        _sddm_qml_tpl =_leer_config ("sddm/Main.qml")
        _sddm_meta =_leer_config ("sddm/metadata.desktop")
        if _sddm_qml_tpl and _sddm_meta :
            _tr_sddm =translations .TRANSLATIONS .get (self ._lang ,translations .TRANSLATIONS ["en"])
            _sddm_qml =(_sddm_qml_tpl
            .replace ("%%SDDM_USER%%",_tr_sddm .get ("lbl-user","Username"))
            .replace ("%%SDDM_PASS%%",_tr_sddm .get ("lbl-pass","Password"))
            .replace ("%%SDDM_SIGNIN%%",_tr_sddm .get ("sddm-signin","Sign In"))
            .replace ("%%SDDM_FAIL%%",_tr_sddm .get ("sddm-fail","Authentication failed. Try again."))
            .replace ("%%SDDM_SESSION%%",_tr_sddm .get ("sddm-session","Session"))
            .replace ("%%SDDM_SUSPEND%%",_tr_sddm .get ("sddm-suspend","Suspend"))
            .replace ("%%SDDM_RESTART%%",_tr_sddm .get ("sddm-restart","Restart"))
            .replace ("%%SDDM_SHUTDOWN%%",_tr_sddm .get ("sddm-shutdown","Shutdown")))
            _sddm_dir =MOUNT_ROOT /"usr"/"share"/"sddm"/"themes"/"avalos"
            _sddm_dir .mkdir (parents =True ,exist_ok =True )
            (_sddm_dir /"metadata.desktop").write_text (_sddm_meta ,encoding ="utf-8")
            (_sddm_dir /"Main.qml").write_text (_sddm_qml ,encoding ="utf-8")
            self ._log (self ._t ("log-sddm-theme-installed"),"ok")
        else :
            # No deberia pasar nunca si build-iso.yml copio bien configs/ al
            # live (mismo mecanismo que ya usan kitty.conf, powermenu.sh,
            # etc. mas arriba) -- si aparece, es señal de que configs/sddm/
            # no llego al ISO, no de que el tema este mal.
            self ._log ("[WARN] configs/sddm/Main.qml o metadata.desktop no encontrados en /usr/share/avalos/configs — tema SDDM no instalado","warn")

        self ._escribir ("etc/sddm.conf.d/hyprland.conf","""\
[Theme]
Current=avalos

[Wayland]
EnableHiDPI=true

[General]
HaltCommand=/usr/bin/systemctl poweroff
RebootCommand=/usr/bin/systemctl reboot
""")

        self ._escribir ("usr/share/wayland-sessions/hyprland.desktop","""\
[Desktop Entry]
Name=Hyprland
Comment=An intelligent dynamic tiling Wayland compositor
Exec=Hyprland
Type=Application
""")

        _gtk_fallback ="""\
[Settings]
gtk-theme-name = Adwaita-dark
gtk-icon-theme-name = Papirus-Dark
gtk-font-name = JetBrainsMono Nerd Font 11
gtk-cursor-theme-name = capitaine-cursors-dark
gtk-cursor-theme-size = 24
gtk-application-prefer-dark-theme = true
"""
        for gtk_ver in ("gtk-3.0","gtk-4.0"):
            # Prioriza configs/gtk/settings.ini del repo (mismo patron que
            # hyprland/waybar/mako/etc mas arriba); si no existe todavia en
            # /usr/share/avalos/configs/gtk/, usa el default de siempre --
            # asi no se rompe nada aunque configs/gtk/ aun no este conectado.
            _gtk_contenido =_leer_config ("gtk/settings.ini")or _gtk_fallback
            self ._escribir (f"{home }/.config/{gtk_ver }/settings.ini",_gtk_contenido )

        bashrc_extra ="""\

# ── AvalOS / Wayland ────────────────────────────────
export QT_QPA_PLATFORM=wayland
export MOZ_ENABLE_WAYLAND=1
export ELECTRON_OZONE_PLATFORM_HINT=auto
export XDG_SESSION_TYPE=wayland
"""
        bashrc_path =MOUNT_ROOT /f"{home }/.bashrc"
        try :
            existing =bashrc_path .read_text (encoding ="utf-8")if bashrc_path .exists ()else ""
            bashrc_path .write_text (existing +bashrc_extra ,encoding ="utf-8")
        except OSError as e :
            self ._log (f"[WARN] .bashrc: {e }","warn")

        _contenido =_leer_config ("fastfetch/config.jsonc")
        if _contenido :

            _tr =translations .TRANSLATIONS .get (self ._lang ,translations .TRANSLATIONS ["en"])

            _ff_keys ={
            '" OS"':f'"{_tr .get ("ff-os"," OS")}"',
            '"\\uf0e4 Host"':f'"{_tr .get ("ff-host","\\uf0e4 Host")}"',
            '" Kernel"':f'"{_tr .get ("ff-kernel"," Kernel")}"',
            '"\\uf55f Uptime"':f'"{_tr .get ("ff-uptime","\\uf55f Uptime")}"',
            '"\\uf439 Packages"':f'"{_tr .get ("ff-packages","\\uf439 Packages")}"',
            '" Shell"':f'"{_tr .get ("ff-shell"," Shell")}"',
            '"\\uf879 Resolution"':f'"{_tr .get ("ff-display","\\uf879 Resolution")}"',
            '" WM"':f'"{_tr .get ("ff-wm"," WM")}"',
            '" Terminal"':f'"{_tr .get ("ff-terminal"," Terminal")}"',
            '" CPU"':f'"{_tr .get ("ff-cpu"," CPU")}"',
            '"\\uf43f GPU"':f'"{_tr .get ("ff-gpu","\\uf43f GPU")}"',
            '"\\uf4cb Disk"':f'"{_tr .get ("ff-disk","\\uf4cb Disk")}"',
            '"\\uf55b RAM"':f'"{_tr .get ("ff-ram","\\uf55b RAM")}"',
            }
            for _old_k ,_new_k in _ff_keys .items ():
                _contenido =_contenido .replace (_old_k ,_new_k )
            self ._escribir (f"{home }/.config/fastfetch/config.jsonc",_contenido )

        _src_logo =Path ("/etc/fastfetch/avalos.txt")
        _dst_logo =MOUNT_ROOT /"etc"/"fastfetch"/"avalos.txt"
        _dst_logo .parent .mkdir (parents =True ,exist_ok =True )
        if _src_logo .exists ():

            shutil .copy2 (_src_logo ,_dst_logo )
            self ._log (self ._t ("log-fastfetch-logo-copied"))
        else :
            self ._log (self ._t ("log-fastfetch-logo-missing"),"warn")

        self ._chown_r (f"/home/{usuario }",usuario )

        ref_conf =MOUNT_ROOT /"etc"/"xdg"/"reflector"/"reflector.conf"
        ref_conf .parent .mkdir (parents =True ,exist_ok =True )
        ref_conf .write_text ("--country SV,US,MX,GT,JP\n--latest 10\n--sort rate\n--protocol https\n")
        self ._run_chroot (["systemctl","enable","reflector.timer"])

        linger =MOUNT_ROOT /"etc/systemd/system/avalos-enable-linger.service"
        linger .parent .mkdir (parents =True ,exist_ok =True )
        linger .write_text (f"""\
[Unit]
Description=Enable linger for {usuario } (PipeWire user services)
After=systemd-logind.service
ConditionPathExists=!/var/lib/systemd/linger/{usuario }

[Service]
Type=oneshot
ExecStart=/usr/bin/loginctl enable-linger {usuario }
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
""")
        self ._run_chroot (["systemctl","enable","avalos-enable-linger.service"])
        self ._log (self ._t ("log-hyprland-ok"),"ok")

    def _run_instalacion (self ):
        self ._instalando =True
        self ._jsc ("pyStartTimer")

        if not self ._config_lista .is_set ():
            if not self ._config_lista .wait (timeout =600 ):
                self ._log (self ._t ("log-timeout-wizard"),"err")
                self ._jsc ("pyErrorPaso",self ._t ("err-timeout"))
                self ._instalando =False
                return
        if self ._abortado :
            self ._instalando =False
            return

        usuario =self ._username
        passw =self ._password
        hostname =self ._hostname
        timezone =self ._timezone

        self ._install_gaming =getattr (self ,'_install_gaming',False )
        self ._install_bore =getattr (self ,'_install_bore',False )

        self ._info ("user",usuario ,"ok")
        self ._info ("modo","USB (ext4 noatime)"if self ._modo_usb else self ._t ("info-modo-pc"),"ok")
        _bl_labels ={"grub":"GRUB","sd-boot":"systemd-boot","refind":"rEFInd","none":self ._t ("info-bootloader-skipped")}
        self ._info ("grub",_bl_labels .get (self ._bootloader ,"GRUB"),
        "ok"if self ._bootloader !="none"else "warn")

        PASOS_IDS =[
        "uefi","net","tools","part","format","mount","mirrors",
        "pacstrap","fstab","config","grub","services","user",
        "aur","hypr","umount",
        ]
        total =len (PASOS_IDS );paso =0

        def avanzar ():
            nonlocal paso ;paso +=1
            self ._progress (int (paso /total *100 ))

        try :

            self ._label (self ._t ("label-detecting-hw"))
            self ._status (self ._t ("status-detecting-hw"))
            discos =listar_discos ()
            disponibles =[d for d in discos if not d ["es_arranque"]]
            disco_boot =next ((d for d in discos if d ["es_arranque"]),None )

            cpu_arch =detectar_cpu_arch_level ()
            gpu_info =detectar_gpu ()
            _es_v3 =cpu_arch in ("x86-64-v3","x86-64-v4")
            if self ._install_bore and _es_v3 :
                _kernel_display ="linux-avalos-bore"
            elif _es_v3 :
                _kernel_display ="linux-avalos"
            else :
                _kernel_display ="linux-avalos-compat"
            self ._log (
            self ._t ("log-summary-pre-kernel",cpu_arch =cpu_arch ,gpu_vendor =gpu_info ["vendor"].upper (),gpu_model =gpu_info ["model"],kernel_display =_kernel_display ),
            "ok"
            )

            self ._info ("ucode",detectar_microcode (),"ok")
            self ._jsc ("pyInfo","dest",
            f"CPU: {cpu_arch } → {_kernel_display } · GPU: {gpu_info ['vendor'].upper ()}","ok")

            if not disponibles :
                self ._jsc ("pyErrorFatal",
                self ._t ("err-no-disk-available",boot_disk =(disco_boot ["name"]if disco_boot else "?")))
                return

            dev_name =self ._disco_destino or disponibles [0 ]["name"]
            disco =next ((d for d in discos if d ["name"]==dev_name ),disponibles [0 ])
            dev_name =disco ["name"]

            if disco ["es_arranque"]:
                self ._jsc ("pyErrorFatal",
                self ._t ("err-disk-is-boot-disk",dev_name =dev_name ))
                return

            size_gb =disco ["size_b"]/1e9
            if size_gb <MIN_DISK_GB :
                self ._jsc ("pyErrorFatal",
                self ._t ("err-disk-too-small",dev_name =dev_name ,size_gb =size_gb ,min_gb =MIN_DISK_GB ))
                return

            dev =f"/dev/{dev_name }"
            disco_tipo =detectar_tipo_disco_destino (dev_name )
            self ._info ("dest",f"{dev } ({disco ['size_human']} · {disco_tipo .upper ()} · {disco ['model']})","ok")
            self ._log (self ._t ("log-target-disk",dev =dev ,size_human =disco ["size_human"],disco_tipo =disco_tipo .upper ()),"ok")

            self ._step ("uefi","active")
            uefi =es_uefi ()
            ucode =detectar_microcode ()
            self ._info ("ucode",ucode ,"ok")

            self ._jsc ("pyBadges",None ,uefi )
            self ._step ("uefi","done","UEFI"if uefi else "BIOS Legacy")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("net","active")
            self ._status (self ._t ("status-checking-internet"))
            net_ok =verificar_internet ()
            self ._jsc ("pyBadges",net_ok ,uefi )
            if not net_ok :
                self ._step ("net","error",self ._t ("step-net-down"))
                self ._jsc ("pyErrorPaso",
                self ._t ("err-no-internet"))
                return
            self ._step ("net","done",self ._t ("step-net-up"))
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("tools","active")
            herramientas =verificar_herramientas ()
            faltantes =[h for h ,ok in herramientas .items ()if not ok ]
            if faltantes :

                _paquetes_faltantes =sorted ({
                _HERRAMIENTA_A_PAQUETE .get (h ,h )for h in faltantes
                })
                self ._log (
                self ._t ("log-missing-tools",faltantes =", ".join (faltantes ),paquetes =", ".join (_paquetes_faltantes )),
                "warn"
                )
                _rc_tools ,_out_tools =self ._run_cmd (["pacman","-Sy","--noconfirm","--needed"]+_paquetes_faltantes ,timeout =120 )
                if _rc_tools !=0 :
                    if self ._salida_indica_error_gpg (_out_tools ):
                        self ._log (self ._t ("log-pacman-gpg-signature-issue"),"err")
                    else :
                        self ._log (self ._t ("log-pacman-sync-failed",rc =_rc_tools ),"warn")
            self ._step ("tools","done")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("part","active")
            self ._status (self ._t ("status-partitioning",dev =dev ))
            self ._log (self ._t ("log-section-partitioning",dev =dev ),"step")

            if not self ._modo_manual :
                self ._jsc ("pyIniciarCountdown",dev ,disco ["model"],disco ["size_human"])
                for i in range (10 ,0 ,-1 ):
                    if self ._abortado :
                        self ._jsc ("pyCerrarCountdown")
                        self ._limpiar_montajes ();return
                    self ._jsc ("pyActualizarCountdown",i -1 )
                    time .sleep (1 )
                self ._jsc ("pyCerrarCountdown")

            if self ._abortado :self ._limpiar_montajes ();return

            # El chequeo de /proc/mounts aplica en ambos modos: en modo
            # manual protege contra que el dropdown del wizard haya
            # apuntado al disco equivocado, exactamente igual que en modo
            # automático protege contra un disco mal seleccionado.
            self ._log (self ._t ("log-checking-mounted-partitions"),"info")
            with open ("/proc/mounts")as _mf :
                _proc_mounts =_mf .read ()
            _dev_base =dev_name
            _mounted =[]
            for _line in _proc_mounts .splitlines ():
                if not _line .strip ():
                    continue
                _parts =_line .split ()
                _src =_parts [0 ].removeprefix ("/dev/")

                if _src .startswith (_dev_base )and _src !=_dev_base :
                    _suffix =_src [len (_dev_base ):]
                    if _suffix and (_suffix [0 ].isdigit ()or _suffix [0 ]=='p'):
                        if _parts [0 ]!=dev :
                            _mounted .append (_parts [1 ])
            if _mounted :
                _puntos =", ".join (_mounted )
                self ._jsc ("pyErrorFatal",
                self ._t ("err-disk-has-mounted-partitions",dev =dev ,puntos =_puntos ))
                return
            self ._log (self ._t ("log-disk-not-mounted",dev =dev ),"ok")

            if self ._modo_manual :
                # ── MODO MANUAL ──────────────────────────────────────────
                # El usuario ya particionó (y puede que ya haya formateado)
                # el disco a mano en una terminal real. dev_efi/dev_root
                # vienen de verificar_particionado_manual()/
                # confirmar_root_manual() (InstaladorAPI), que ya los
                # validó contra detectar_particiones_manual() — no se
                # vuelve a tocar el esquema de particiones acá.
                dev_efi =self ._modo_manual_efi
                dev_root =self ._modo_manual_root

                if not dev_root :
                    self ._step ("part","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-manual-no-root-selected"))
                    self ._limpiar_montajes ();return

                if uefi and not dev_efi :
                    self ._step ("part","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-manual-no-efi-found"))
                    self ._limpiar_montajes ();return

                if uefi and dev_efi :
                    # Mismo criterio que para root: blkid vacío/rc!=0 =
                    # sin filesystem reconocible = el usuario dejó la
                    # partición EFI creada pero sin formatear a propósito.
                    # Se formatea con el mismo comando que usa el modo
                    # automático (mkfs.fat -F32) — si ya tiene FAT32 u
                    # otro filesystem, se respeta tal cual, igual que root.
                    _rc_efi ,_fstype_efi ,_ =_ejecutar (["blkid","-s","TYPE","-o","value",dev_efi ])
                    _fstype_efi =_fstype_efi .strip ()if _rc_efi ==0 else ""
                    if not _fstype_efi :
                        rc_efi_fmt ,_ =self ._run_cmd (["mkfs.fat","-F32",dev_efi ])
                        if rc_efi_fmt !=0 :
                            self ._step ("part","error")
                            self ._jsc ("pyErrorPaso",self ._t ("err-mkfs-fat-failed",dev_efi =dev_efi ))
                            self ._limpiar_montajes ();return
                        self ._log (self ._t ("log-manual-efi-formatted",dev_efi =dev_efi ),"ok")
                    else :
                        self ._log (self ._t ("log-manual-fs-detected",dev_root =dev_efi ,fstype =_fstype_efi ),"ok")

                self ._step ("part","done",self ._t ("step-manual-partitions-detected"))
                avanzar ()

                if self ._abortado :self ._limpiar_montajes ();return

                self ._step ("format","active")
                self ._status (self ._t ("status-formatting"))
                self ._log (self ._t ("log-section-formatting"),"step")

                # ¿La root ya está formateada? blkid con salida vacía/rc!=0
                # significa "sin filesystem reconocible" — en ese caso el
                # usuario dejó la partición sin formatear a propósito
                # (creó el esquema pero delega el mkfs al instalador) y sí
                # se formatea acá, igual que en modo automático.
                _rc_fs ,_fstype_actual ,_ =_ejecutar (["blkid","-s","TYPE","-o","value",dev_root ])
                _fstype_actual =_fstype_actual .strip ()if _rc_fs ==0 else ""

                if not _fstype_actual :
                    if self ._modo_usb :
                        rc ,_ =self ._run_cmd (["mkfs.ext4","-O","^has_journal","-F",dev_root ])
                    else :
                        rc ,_ =self ._run_cmd (["mkfs.btrfs","-f","-L","AvalOS",dev_root ])
                    if rc !=0 :
                        self ._step ("format","error")
                        self ._jsc ("pyErrorPaso",self ._t ("err-mkfs-failed",dev_root =dev_root ))
                        self ._limpiar_montajes ();return
                    _fstype_actual ="ext4"if self ._modo_usb else "btrfs"
                else :
                    self ._log (self ._t ("log-manual-fs-detected",dev_root =dev_root ,fstype =_fstype_actual ),"ok")

                if _fstype_actual =="btrfs"and not self ._modo_usb :
                    _btrfs_tmp ="/tmp/btrfs_setup"
                    rc_mnt ,_ =self ._run_cmd (["mount",dev_root ,_btrfs_tmp ,"-o","compress=zstd"],
                    pre_mkdir =_btrfs_tmp )
                    if rc_mnt !=0 :
                        self ._step ("format","error")
                        self ._jsc ("pyErrorPaso",self ._t ("err-btrfs-mount-failed"))
                        self ._limpiar_montajes ();return

                    # Según lo acordado: crear solo los subvolúmenes que
                    # falten, sin pisar los que el usuario ya armó a mano.
                    _existentes =set (self ._modo_manual_subvols_existentes )
                    _subvols =["@","@home","@snapshots","@log","@cache","@tmp"]
                    _creados =[]
                    for sv in _subvols :
                        if sv in _existentes :
                            self ._log (self ._t ("log-subvol-already-exists",sv =sv ),"info")
                            continue
                        rc_sv ,_ =self ._run_cmd (["btrfs","subvolume","create",
                        f"{_btrfs_tmp }/{sv }"])
                        if rc_sv !=0 :
                            self ._log (self ._t ("log-subvol-create-fail",sv =sv ),"warn")
                        else :
                            _creados .append (sv )

                    self ._run_cmd (["umount",_btrfs_tmp ])
                    if _creados :
                        self ._log (self ._t ("log-subvols-created",subvols =", ".join (_creados )),"ok")

                _fmt_label =self ._t ("step-fmt-manual-detected",fstype =_fstype_actual .upper ())
                self ._step ("format","done",_fmt_label )

                try :
                    subprocess .run (["udevadm","settle","--timeout=5"],check =False )
                except Exception :
                    time .sleep (1 )
                avanzar ()

            else :
                # ── MODO AUTOMÁTICO ──────────────────────────────────────
                # FIX (particionado): 'wipefs' puede fallar con
                # "probing initialization failed: Device or resource busy"
                # aunque el disco no esté montado (confirmado en /proc/mounts
                # arriba). Es una condición de carrera conocida y documentada
                # en udisks2/udev: el kernel abre brevemente el device node
                # para (re)enumerar metadata justo después de que un disco
                # nuevo aparece o cambia, y wipefs no puede abrirlo con O_EXCL
                # mientras tanto. Es transitorio — 'udevadm settle' + reintentos
                # con backoff es la mitigación estándar (mismo patrón que usa
                # ceph-volume en producción, ver comentario "workaround probable
                # race condition" en su código). No hay garantía de timing
                # exacta (systemd-udev-settle.service(8) es explícito: "There
                # can be no guarantee that hardware is fully discovered at any
                # specific time"), por eso reintentamos en vez de esperar una
                # sola vez.
                try :
                    subprocess .run (["udevadm","settle","--timeout=5"],check =False )
                except Exception :
                    pass

                rc_wipe =1
                _wipe_out =""
                for _intento in range (1 ,4 ):
                    _wipe_cmd =["wipefs","-a",dev ]
                    if _intento ==3 :
                        # Último intento: --force evita el chequeo O_EXCL de
                        # wipefs (confirmado en 'wipefs --help' del propio
                        # binario). Solo se usa acá, no antes — los intentos
                        # 1-2 son "limpios" (settle + retry) para no enmascarar
                        # un problema real si /proc/mounts tuviera un falso
                        # negativo por alguna razón.
                        _wipe_cmd =["wipefs","-a","-f",dev ]
                    rc_wipe ,_wipe_out =self ._run_cmd (_wipe_cmd )
                    if rc_wipe ==0 :
                        break
                    if _intento <3 :
                        self ._log (
                        self ._t ("log-wipefs-retry",intento =_intento ,dev =dev ),
                        "warn")
                        try :
                            subprocess .run (["udevadm","settle","--timeout=5"],check =False )
                        except Exception :
                            pass
                        time .sleep (2 *_intento )
                if rc_wipe !=0 :
                    self ._step ("part","error")
                    self ._jsc ("pyErrorPaso",
                    self ._t ("err-wipefs-failed",dev =dev ))
                    self ._limpiar_montajes ();return

                if uefi :

                    rc ,_ =self ._run_cmd ([
                    "parted","-s",dev ,
                    "mklabel","gpt",
                    "mkpart","ESP","fat32","1MiB","513MiB",
                    "set","1","esp","on",
                    "mkpart","root","ext4","513MiB","100%",
                    ])
                    dev_efi =dev +("p1"if "nvme"in dev_name or "mmcblk"in dev_name else "1")
                    dev_root =dev +("p2"if "nvme"in dev_name or "mmcblk"in dev_name else "2")
                else :

                    rc ,_ =self ._run_cmd ([
                    "parted","-s",dev ,
                    "mklabel","msdos",
                    "mkpart","primary","ext4","1MiB","100%",
                    "set","1","boot","on",
                    ])
                    dev_root =dev +("p1"if "nvme"in dev_name or "mmcblk"in dev_name else "1")
                    dev_efi =""

                if rc !=0 :
                    self ._step ("part","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-parted-failed",dev =dev ))
                    self ._limpiar_montajes ();return

                try :
                    subprocess .run (["udevadm","settle","--timeout=5"],check =False )
                except Exception :
                    time .sleep (2 )
                self ._step ("part","done",
                "GPT: EFI (512MB) + root"if uefi else "MBR: root (100%)")
                avanzar ()

                if self ._abortado :self ._limpiar_montajes ();return

                self ._step ("format","active")
                self ._status (self ._t ("status-formatting"))
                self ._log (self ._t ("log-section-formatting"),"step")

                if uefi :
                    rc ,_ =self ._run_cmd (["mkfs.fat","-F32",dev_efi ])
                    if rc !=0 :
                        self ._step ("format","error")
                        self ._jsc ("pyErrorPaso",self ._t ("err-mkfs-fat-failed",dev_efi =dev_efi ))
                        self ._limpiar_montajes ();return

                if self ._modo_usb :
                    rc ,_ =self ._run_cmd (["mkfs.ext4","-O","^has_journal","-F",dev_root ])
                else :
                    rc ,_ =self ._run_cmd (["mkfs.btrfs","-f","-L","AvalOS",dev_root ])

                if rc !=0 :
                    self ._step ("format","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-mkfs-failed",dev_root =dev_root ))
                    self ._limpiar_montajes ();return

                if not self ._modo_usb :
                    _btrfs_tmp ="/tmp/btrfs_setup"
                    rc_mnt ,_ =self ._run_cmd (["mount",dev_root ,_btrfs_tmp ,"-o","compress=zstd"],
                    pre_mkdir =_btrfs_tmp )
                    if rc_mnt !=0 :
                        self ._step ("format","error")
                        self ._jsc ("pyErrorPaso",self ._t ("err-btrfs-mount-failed"))
                        self ._limpiar_montajes ();return

                    _subvols =["@","@home","@snapshots","@log","@cache","@tmp"]
                    for sv in _subvols :
                        rc_sv ,_ =self ._run_cmd (["btrfs","subvolume","create",
                        f"{_btrfs_tmp }/{sv }"])
                        if rc_sv !=0 :
                            self ._log (self ._t ("log-subvol-create-fail",sv =sv ),"warn")

                    self ._run_cmd (["umount",_btrfs_tmp ])
                    self ._log (self ._t ("log-subvols-created",subvols =", ".join (_subvols )),"ok")

                if uefi and self ._modo_usb :
                    _fmt_label ="FAT32 + "+self ._t ("step-fmt-ext4-nojournal")
                elif uefi :
                    _fmt_label ="FAT32 + Btrfs (@, @home, @snapshots, @log, @cache, @tmp)"
                else :
                    _fmt_label =self ._t ("step-fmt-ext4-nojournal")if self ._modo_usb else "Btrfs (@, @home, @snapshots, @log, @cache, @tmp)"
                self ._step ("format","done",_fmt_label )

                try :
                    subprocess .run (["udevadm","settle","--timeout=5"],check =False )
                except Exception :
                    time .sleep (1 )
                avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("mount","active")
            MOUNT_ROOT .mkdir (parents =True ,exist_ok =True )

            if self ._modo_usb :

                rc ,_ =self ._run_cmd (["mount",dev_root ,str (MOUNT_ROOT )])
                if rc !=0 :
                    self ._step ("mount","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-mount-failed",dev_root =dev_root ))
                    self ._limpiar_montajes ();return
            else :

                _btrfs_opts ="compress=zstd,noatime,space_cache=v2"

                rc ,_ =self ._run_cmd (["mount","-o",
                f"subvol=@,{_btrfs_opts }",
                dev_root ,str (MOUNT_ROOT )])
                if rc !=0 :
                    self ._step ("mount","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-mount-subvol-failed",dev_root =dev_root ))
                    self ._limpiar_montajes ();return

                _sv_mounts =[
                ("@home",MOUNT_ROOT /"home"),
                ("@snapshots",MOUNT_ROOT /".snapshots"),
                ("@log",MOUNT_ROOT /"var"/"log"),
                ("@cache",MOUNT_ROOT /"var"/"cache"),
                ("@tmp",MOUNT_ROOT /"tmp"),
                ]
                for sv_name ,sv_path in _sv_mounts :
                    sv_path .mkdir (parents =True ,exist_ok =True )
                    _sv_opts =f"subvol={sv_name },{_btrfs_opts }"

                    if sv_name =="@tmp":
                        _sv_opts +=",nodatacow"
                    rc_sv ,_ =self ._run_cmd (["mount","-o",_sv_opts ,dev_root ,str (sv_path )])
                    if rc_sv !=0 :
                        self ._log (self ._t ("log-subvol-mount-fail",sv_name =sv_name ,sv_path =sv_path ),"warn")
                    elif sv_name =="@tmp":

                        self ._run_cmd (["chattr","+C",str (sv_path )])
                        self ._log (self ._t ("log-tmp-cow-disabled"),"ok")

                self ._log (self ._t ("log-subvols-mounted-ok"),"ok")

            if uefi :
                MOUNT_EFI .mkdir (parents =True ,exist_ok =True )
                rc ,_ =self ._run_cmd (["mount",dev_efi ,str (MOUNT_EFI )])
                if rc !=0 :
                    self ._step ("mount","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-mount-efi-failed",dev_efi =dev_efi ))
                    self ._limpiar_montajes ();return

            self ._step ("mount","done")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            # Sincronizacion de hora ANTES de cualquier operacion de red: si
            # el reloj del sistema esta mal (bateria CMOS muerta, o NTP que
            # no alcanzo a sincronizar en el boot), la validacion de
            # certificado TLS puede fallar igual contra CUALQUIER mirror --
            # no es un problema de "este mirror en particular", es la hora
            # local. Forzamos esto antes de tocar reflector/pacman.
            self ._log (self ._t ("log-timesync-start"),"info")
            self ._run_cmd (["timedatectl","set-ntp","true"],timeout =10 )
            for _ts_intento in range (10 ):
                _ts_rc ,_ts_out =self ._run_cmd (
                ["timedatectl","show","-p","NTPSynchronized","--value"],timeout =5
                )
                if _ts_rc ==0 and "yes"in _ts_out .strip ().lower ():
                    self ._log (self ._t ("log-timesync-ok"),"ok")
                    break
                time .sleep (1 )
            else :
                self ._log (self ._t ("log-timesync-timeout"),"warn")

            self ._step ("mirrors","active")
            self ._status (self ._t ("status-optimizing-mirrors"))
            self ._log (self ._t ("log-section-mirrors"),"step")

            _rc_rm_install ,_ =self ._run_cmd (["pacman","-Sy","--noconfirm","--needed","rate-mirrors"],timeout =120 )
            _mirrors_ok =False
            if _rc_rm_install ==0 :
                _rc_rm ,_ =self ._run_cmd ([
                "rate-mirrors","arch","--allow-root","--save","/etc/pacman.d/mirrorlist",
                ],timeout =90 )
                if _rc_rm ==0 :
                    _mirrors_ok =True
                    self ._step ("mirrors","done",self ._t ("step-mirrors-optimized"))
                    self ._log (self ._t ("log-ratemirrors-ok"),"ok")

            if _mirrors_ok :
                try :
                    with open ("/etc/pacman.d/mirrorlist","a")as _mlf :
                        _mlf .write (
                        "\n# Fallback agregado por el instalador: mirror grande y "
                        "siempre completo (incluye multilib), por si el mirror "
                        "elegido igual tiene algun hueco\n"
                        "Server = https://mirror.rackspace.com/archlinux/$repo/os/$arch\n"
                        )
                except Exception as _e_ml :
                    self ._log (f"[WARN] No se pudo agregar mirror de respaldo: {_e_ml }","warn")
            else :
                self ._log (self ._t ("log-ratemirrors-fallback"),"warn")
                _rc_refl_install ,_out_refl_install =self ._run_cmd (["pacman","-Sy","--noconfirm","--needed","reflector"],timeout =120 )
                if _rc_refl_install !=0 :
                    self ._step ("mirrors","skip",self ._t ("step-mirrors-default"))
                    if self ._salida_indica_error_gpg (_out_refl_install ):
                        self ._log (self ._t ("log-pacman-gpg-signature-issue"),"err")
                    else :
                        self ._log (self ._t ("log-reflector-install-fail"),"warn")
                else :
                    rc ,_ =self ._run_cmd ([
                    "reflector","--country","SV,US,MX,GT,JP",
                    "--latest","10","--sort","rate",
                    "--protocol","https","--save","/etc/pacman.d/mirrorlist",
                    ],timeout =120 )
                    if rc ==0 :
                        self ._step ("mirrors","done",self ._t ("step-mirrors-optimized"))
                        try :
                            with open ("/etc/pacman.d/mirrorlist","a")as _mlf :
                                _mlf .write (
                                "\n# Fallback agregado por el instalador: mirror grande y "
                                "siempre completo (incluye multilib), por si los mirrors "
                                "regionales de reflector tienen multilib incompleto/viejo\n"
                                "Server = https://mirror.rackspace.com/archlinux/$repo/os/$arch\n"
                                )
                        except Exception as _e_ml :
                            self ._log (f"[WARN] No se pudo agregar mirror de respaldo: {_e_ml }","warn")
                    else :
                        self ._step ("mirrors","skip",self ._t ("step-mirrors-default"))
                        self ._log (self ._t ("log-reflector-fail"),"warn")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("pacstrap","active")
            self ._status (self ._t ("status-installing-base"))
            self ._label (self ._t ("label-installing-base"))
            self ._log ("\n── pacstrap ──\n","step")

            pkgs =list (BASE_PKGS )

            if not self ._modo_usb :
                pkgs +=BTRFS_PKGS
            if self ._bootloader =='sd-boot':

                pkgs =[p for p in pkgs if p not in {"grub","os-prober"}]
            elif self ._bootloader =='refind':

                pkgs =[p for p in pkgs if p not in {"grub","os-prober"}]
            elif self ._bootloader =='none':
                pkgs =[p for p in pkgs if p not in {"grub","efibootmgr","os-prober"}]

            _es_v3_o_superior =cpu_arch in ("x86-64-v3","x86-64-v4")
            _nombre_cpu_nivel ="v3/v4 (AVX2+)"if _es_v3_o_superior else "baseline (sin AVX2)"
            self ._log (self ._t ("log-cpu-detected",cpu_arch =cpu_arch ,nivel =_nombre_cpu_nivel ),"info")

            _quiere_bore =bool (getattr (self ,"_install_bore",False ))
            if _quiere_bore and not _es_v3_o_superior :
                self ._log (
                self ._t ("log-bore-not-supported",cpu_arch =cpu_arch ),
                "warn"
                )
                _quiere_bore =False

            self ._log (self ._t ("log-checking-kernel-repo"),"info")

            if _quiere_bore :
                _target_kernel ="linux-avalos-bore"
                _target_headers ="linux-avalos-bore-headers"
            elif _es_v3_o_superior :
                _target_kernel ="linux-avalos"
                _target_headers ="linux-avalos-headers"
            else :
                _target_kernel ="linux-avalos-compat"
                _target_headers ="linux-avalos-compat-headers"

            def _pacman_disponible (pkg ,intentos =4 ,espera =6 ):
                _ultima_salida =""
                for i in range (intentos ):
                    _cmd =["pacman","-Syi"if i ==0 else "-Syyi","--noconfirm",pkg ]
                    _rc ,_ultima_salida =self ._run_cmd (_cmd ,timeout =25 ,log_cls ="info")
                    if _rc ==0 :
                        return True
                    if i <intentos -1 :
                        self ._log (
                        self ._t ("log-kernel-retry",pkg =pkg ,intento =i +2 ,total =intentos ),
                        "warn"
                        )
                        time .sleep (espera )
                if self ._salida_indica_error_gpg (_ultima_salida ):
                    self ._log (self ._t ("log-pacman-gpg-signature-issue"),"err")
                return False

            _kernel_pkg =None
            _headers_pkg =None

            try :
                if _pacman_disponible (_target_kernel ):
                    _kernel_pkg ,_headers_pkg =_target_kernel ,_target_headers
                    self ._log (self ._t ("log-kernel-available",kernel_pkg =_kernel_pkg ),"ok")

                elif _quiere_bore and _pacman_disponible ("linux-avalos"):
                    # BORE no publicado — mismo nivel de CPU sin BORE es seguro
                    # (mismo -march, solo cambia el scheduler).
                    _kernel_pkg ,_headers_pkg ="linux-avalos","linux-avalos-headers"
                    self ._log (
                    self ._t ("log-kernel-fallback-no-bore",target =_target_kernel ,alt =_kernel_pkg ,cpu_arch =cpu_arch ),
                    "warn"
                    )
                # Si el objetivo es avalos o avalos-compat y no está disponible,
                # NO cambiamos de nivel de CPU — instalar v3 sin AVX2 (o al revés)
                # puede no arrancar. Mejor bloquear con error claro que arriesgar
                # un sistema que no bootea o meter un kernel que no sea AvalOS.

            except Exception as _e :
                self ._log (self ._t ("log-kernel-repo-query-error",e =_e ),"warn")

            if not _kernel_pkg :
                self ._jsc ("pyErrorFatal",self ._t ("err-avalos-repo-unreachable",target =_target_kernel ))
                return

            pkgs +=[_kernel_pkg ,_headers_pkg ]

            pkgs +=gpu_info ["pkgs"]+HYPRLAND_PKGS +([ucode ]if ucode else [])

            if self ._install_gaming :
                pkgs +=GAMING_PKGS
                self ._log (self ._t ("log-gaming-enabled"),"ok")
            else :
                self ._log (self ._t ("log-gaming-skipped"),"info")
            self ._log (self ._t ("log-gpu-detected",gpu_vendor =gpu_info ["vendor"].upper (),drivers =", ".join (gpu_info ["pkgs"][:3 ])),"info")
            self ._log (self ._t ("log-total-packages",total =len (pkgs ),preview =", ".join (pkgs [:8 ]),extra =max (0 ,len (pkgs )-8 )),"info")

            self ._log (self ._t ("log-checking-multilib"),"info")
            _pkgs_omitidos =[]
            while True :
                _pf_ok =False
                _pf_out =""
                for _pf_intento in range (3 ):
                    _pf_cmd =["pacman","-Sp"if _pf_intento ==0 else "-Syyp","--noconfirm"]+pkgs
                    _pf_rc ,_pf_out =self ._run_cmd (_pf_cmd ,timeout =60 ,log_cls ="info")
                    if _pf_rc ==0 :
                        _pf_ok =True
                        break
                    if _pf_intento <2 :
                        self ._log (
                        self ._t ("log-kernel-retry",pkg ="multilib",intento =_pf_intento +2 ,total =3 ),
                        "warn"
                        )
                        time .sleep (6 )
                if _pf_ok :
                    break

                _pf_faltantes =sorted (set (re .findall (r"target not found:\s*(\S+)",_pf_out )))
                _pf_recortables =[p for p in _pf_faltantes if p .startswith ("lib32-")]
                if _pf_recortables and all (p in pkgs for p in _pf_recortables ):
                    # Se puede recortar: son paquetes lib32- explícitos de
                    # NUESTRA lista (no dependencias transitivas de otra
                    # cosa), así que sacarlos es seguro y no deja nada a
                    # medias. Visto en producción (hilo de CachyOS, abr-may
                    # 2026, CVE en el stack multimedia lib32): Arch a veces
                    # retira paquetes lib32-gst-*/lib32-sdl2* de multilib
                    # entero por semanas mientras responde a un CVE — pasa
                    # en TODOS los mirrors por igual, así que ni reintentar
                    # ni cambiar de mirror lo arregla. Mejor seguir sin
                    # ellos que bloquear toda la instalación por un extra
                    # de compatibilidad.
                    #
                    # El recorte queda LIMITADO a lib32- a propósito: un
                    # 'target not found' en linux-avalos-firmware, un
                    # kernel, o cualquier otro paquete no-lib32 NUNCA se
                    # auto-recorta en silencio — cae al diálogo de mirror
                    # de abajo, porque faltar ahí sí deja un sistema roto
                    # (sin firmware de hardware, sin kernel, etc), a
                    # diferencia de un extra de compatibilidad multilib.
                    for _p in _pf_recortables :
                        pkgs .remove (_p )
                    _pkgs_omitidos +=_pf_recortables
                    self ._log (
                    self ._t ("log-multilib-pkg-dropped",pkgs =", ".join (_pf_recortables )),
                    "warn"
                    )
                    continue

                # Ya no hay más que recortar y sigue fallando — esto no es
                # "un par de extras caídos", puede ser el mirror/red. Aquí
                # sí conviene que decida el usuario.
                _pf_detalle =", ".join (_pf_faltantes )if _pf_faltantes else _pf_out .strip ()[-300 :]
                self ._jsc ("pyMirrorDialog",_pf_detalle )
                while not self ._mirror_choice_event .wait (timeout =1.0 ):
                    if self ._abortado :
                        self ._limpiar_montajes ();return
                self ._mirror_choice_event .clear ()
                _choice =self ._mirror_choice
                self ._mirror_choice =None
                if self ._abortado :
                    self ._limpiar_montajes ();return
                if _choice =="aceptar":
                    self ._log (self ._t ("log-mirror-broadening"),"info")
                    self ._run_cmd (
                    ["reflector","--latest","15","--sort","rate","--protocol","https",
                    "--save","/etc/pacman.d/mirrorlist"],timeout =120
                    )
                elif _choice !="reintentar":
                    # "rechazar" (o cierre inesperado del diálogo): el
                    # usuario prefiere resolverlo por su cuenta — cortamos
                    # con el mismo error claro de siempre y lo dejamos usar
                    # el botón "Reintentar" global cuando esté listo.
                    self ._jsc ("pyErrorFatal",self ._t ("err-multilib-unreachable",detalle =_pf_detalle ))
                    return
                # "reintentar": vuelve a probar tal cual, con los mismos mirrors

            if _pkgs_omitidos :
                self ._log (
                self ._t ("log-multilib-pkgs-omitidos",pkgs =", ".join (sorted (set (_pkgs_omitidos )))),
                "warn"
                )

            _pacstrap_ok =False
            _pacstrap_out =""
            for _pd_val in (None ,2 ,1 ):
                if self ._abortado :self ._limpiar_montajes ();return
                if _pd_val is not None :
                    # Solo llegamos aca si el intento anterior fallo con
                    # "failed retrieving file" para TODOS/casi todos los
                    # paquetes -- eso, con el preflight de resolucion ya
                    # habiendo pasado antes, es la firma tipica de una
                    # conexion que no aguanta N descargas grandes en
                    # paralelo (ParallelDownloads=5 por defecto). Bajar el
                    # paralelismo no arregla un mirror caido, pero si
                    # arregla esto -- que es lo que se vio en pruebas reales
                    # (los .db, chicos, entraban bien; firefox/wine/firmware,
                    # grandes, fallaban todos).
                    self ._run_cmd (
                    ["sed","-i",f"s/^ParallelDownloads.*/ParallelDownloads = {_pd_val }/","/etc/pacman.conf"],
                    timeout =10
                    )
                    self ._log (self ._t ("log-pacstrap-retry-slower",n =_pd_val ),"warn")
                rc ,_pacstrap_out =self ._run_cmd (
                ["pacstrap","-c",str (MOUNT_ROOT )]+pkgs ,
                timeout =3600 ,log_cls ="info"
                )
                if rc ==0 :
                    _pacstrap_ok =True
                    break
                if "failed retrieving file"not in _pacstrap_out :
                    # Otro tipo de fallo (disco lleno, permisos, etc) --
                    # bajar el paralelismo no va a arreglar nada, no vale
                    # la pena seguir reintentando.
                    break

            if not _pacstrap_ok :
                self ._step ("pacstrap","error")
                self ._jsc ("pyErrorPaso",self ._t ("err-pacstrap-failed"))
                self ._limpiar_montajes ();return

            self ._step ("pacstrap","done")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("fstab","active")
            self ._status (self ._t ("status-generating-fstab"))
            rc ,fstab_out =self ._run_cmd (["genfstab","-U",str (MOUNT_ROOT )])
            if rc !=0 or not fstab_out .strip ():
                self ._step ("fstab","error")
                self ._jsc ("pyErrorPaso",self ._t ("err-genfstab-failed"))
                self ._limpiar_montajes ();return

            if self ._modo_usb :

                fstab_out =fstab_out .replace ("relatime","noatime")

                def _add_noatime (m ):
                    opts =m .group (0 )
                    if "noatime"not in opts and "vfat"not in opts .lower ():
                        return opts .replace ("defaults","defaults,noatime",1 )
                    return opts
                fstab_out =re .sub (r'(defaults[^\s]*)',_add_noatime ,fstab_out )

            # subvolid=NNN (que genfstab -U inserta solo en lineas Btrfs) es
            # una referencia ABSOLUTA al subvolumen -- tiene prioridad sobre
            # subvol=@nombre y por eso ROMPE grub-btrfs: al arrancar una
            # snapshot desde el menu de GRUB, el kernel monta la snapshot
            # via cmdline, pero systemd despues remonta root segun fstab, y
            # con subvolid= fijo siempre vuelve al @ original sin importar
            # que snapshot se eligio. Se saca en las dos posiciones posibles
            # (antes o al final de la lista de opciones) para dejar solo
            # subvol=@... funcionando como se espera.
            fstab_out =re .sub (r'subvolid=\d+,','',fstab_out )
            fstab_out =re .sub (r',subvolid=\d+','',fstab_out )

            try :
                (MOUNT_ROOT /"etc"/"fstab").write_text (fstab_out +"\n")
            except OSError as e :
                self ._step ("fstab","error")
                self ._jsc ("pyErrorPaso",self ._t ("err-fstab-write-failed",e =e ))
                self ._limpiar_montajes ();return

            self ._step ("fstab","done")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("config","active")
            self ._status (self ._t ("status-configuring-system"))
            self ._log (self ._t ("log-section-system-config"),"step")

            self ._run_chroot (["ln","-sf",f"/usr/share/zoneinfo/{timezone }","/etc/localtime"])
            self ._run_chroot (["hwclock","--systohc"])

            _loc =self ._locale
            _loc_gen =f"{_loc } UTF-8"
            _keymap =self ._keymap

            _loc_gen_extra ="en_US.UTF-8 UTF-8"

            _extra_locales =[_loc_gen ,_loc_gen_extra ]
            if _loc .startswith ("zh_")and "zh_CN.UTF-8 UTF-8"not in _extra_locales :
                _extra_locales .append ("zh_CN.UTF-8 UTF-8")

            locale_gen =MOUNT_ROOT /"etc"/"locale.gen"
            if locale_gen .exists ():
                txt =locale_gen .read_text ()
                for loc_entry in _extra_locales :

                    txt =txt .replace (f"#{loc_entry }",loc_entry )
                    txt =txt .replace (f"# {loc_entry }",loc_entry )

                    if loc_entry not in txt :
                        txt +=f"\n{loc_entry }\n"
                locale_gen .write_text (txt )
            else :

                self ._log (self ._t ("log-localegen-missing"),"warn")
                locale_gen .parent .mkdir (parents =True ,exist_ok =True )
                locale_gen .write_text ("\n".join (_extra_locales )+"\n")
            self ._run_chroot (["locale-gen"])
            (MOUNT_ROOT /"etc"/"locale.conf").write_text (f"LANG={_loc }\n")
            (MOUNT_ROOT /"etc"/"vconsole.conf").write_text (f"KEYMAP={_keymap }\n")
            self ._log (self ._t ("log-locale-keymap",loc =_loc ,keymap =_keymap ),"ok")
            (MOUNT_ROOT /"etc"/"hostname").write_text (hostname +"\n")
            (MOUNT_ROOT /"etc"/"hosts").write_text (
            f"127.0.0.1   localhost\n::1         localhost\n127.0.1.1   {hostname }.localdomain {hostname }\n"
            )

            rc_pw ,out_pw =self ._run_chroot_stdin (f"root:{passw }\n",["chpasswd"])
            if rc_pw !=0 :
                self ._log (self ._t ("log-chpasswd-root-fail",rc =rc_pw ,out =out_pw ),"err")
                self ._limpiar_montajes ()
                return

            if not self ._modo_usb :
                _mkinit_path =MOUNT_ROOT /"etc"/"mkinitcpio.conf"
                if _mkinit_path .exists ():
                    _mkinit_txt =_mkinit_path .read_text ()

                    if "btrfs"not in _mkinit_txt :
                        _mkinit_txt =re .sub (
                        r'^(HOOKS=\([^)]*)\bfilesystems\b',
                        r'\1btrfs filesystems',
                        _mkinit_txt ,
                        flags =re .MULTILINE
                        )
                        _mkinit_path .write_text (_mkinit_txt )
                        self ._log (self ._t ("log-mkinitcpio-btrfs-added"),"ok")
                    else :
                        self ._log (self ._t ("log-mkinitcpio-btrfs-present"),"ok")

                    _mkinit_txt =_mkinit_path .read_text ()
                    if ("grub-btrfs-overlayfs"not in _mkinit_txt
                    and self ._bootloader =="grub"):
                        _mkinit_txt =re .sub (
                        r'^(HOOKS=\([^)]*)\bfsck\b',
                        r'\1fsck grub-btrfs-overlayfs',
                        _mkinit_txt ,
                        flags =re .MULTILINE
                        )
                        _mkinit_path .write_text (_mkinit_txt )
                        self ._log (self ._t ("log-mkinitcpio-overlayfs-added"),"ok")

                _grub_default =MOUNT_ROOT /"etc"/"default"/"grub"
                if _grub_default .exists ():
                    _grub_txt =_grub_default .read_text ()
                    _grub_btrfs_additions =[]
                    if "GRUB_BTRFS_OVERRIDE_BOOT_PARTITION_DETECTION"not in _grub_txt :
                        _grub_btrfs_additions .append (
                        "GRUB_BTRFS_OVERRIDE_BOOT_PARTITION_DETECTION=true"
                        )

                    if "GRUB_DISABLE_OS_PROBER"not in _grub_txt :
                        _grub_btrfs_additions .append ("GRUB_DISABLE_OS_PROBER=false")
                    if _grub_btrfs_additions :
                        _grub_txt +="\n# AvalOS Btrfs snapshot support\n"
                        _grub_txt +="\n".join (_grub_btrfs_additions )+"\n"
                        _grub_default .write_text (_grub_txt )
                        self ._log (self ._t ("log-grub-btrfs-configured"),"ok")

            self ._run_chroot (["mkinitcpio","-P"])
            self ._step ("config","done","locale · timezone · hostname · initramfs · btrfs-hook"
            if not self ._modo_usb else "locale · timezone · hostname · initramfs")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("grub","active")
            if self ._bootloader =='none':
                self ._step ("grub","skip",self ._t ("step-bootloader-skipped-label"))
                self ._log (self ._t ("log-bootloader-skipped"),"warn")
                avanzar ()

            elif self ._bootloader =='grub':
                self ._status (self ._t ("status-installing-grub"))
                self ._log (self ._t ("log-section-installing-grub"),"step")
                if uefi :
                    grub_cmd =["grub-install","--target=x86_64-efi",
                    "--efi-directory=/boot/efi","--bootloader-id=GRUB"]

                    if GRUB_UEFI_REMOVABLE or self ._modo_usb :
                        grub_cmd .append ("--removable")
                    rc ,_ =self ._run_chroot (grub_cmd )

                    # Respaldo: en instalacion normal (con entrada NVRAM),
                    # instalar TAMBIEN en la ruta fija /EFI/BOOT/BOOTX64.EFI.
                    # Protege contra NVRAM corrupta/reseteada/no soportada
                    # que dejaria el disco sin forma de arrancar aunque
                    # grub-install haya funcionado bien en su momento. No
                    # bloquea la instalacion si este paso extra falla.
                    if rc ==0 and not (GRUB_UEFI_REMOVABLE or self ._modo_usb ):
                        _rc_rem ,_ =self ._run_chroot ([
                        "grub-install","--target=x86_64-efi",
                        "--efi-directory=/boot/efi","--removable"
                        ])
                        self ._log (
                        self ._t ("log-grub-removable-ok"if _rc_rem ==0 else "log-grub-removable-fail"),
                        "ok"if _rc_rem ==0 else "warn"
                        )
                else :
                    rc ,_ =self ._run_chroot (["grub-install","--target=i386-pc",dev ])

                if rc !=0 :
                    self ._step ("grub","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-grub-install-failed"))
                    self ._limpiar_montajes ();return

                gd_path =MOUNT_ROOT /"etc"/"default"/"grub"
                if gd_path .exists ():
                    lines =[l for l in gd_path .read_text ().splitlines ()
                    if not l .strip ().startswith ("GRUB_DISABLE_OS_PROBER")]
                    lines .append ("GRUB_DISABLE_OS_PROBER=false")
                    gd_path .write_text ("\n".join (lines )+"\n")
                self ._run_chroot (["grub-mkconfig","-o","/boot/grub/grub.cfg"])
                self ._step ("grub","done",self ._t ("step-grub-installed-label"))
                avanzar ()

            elif self ._bootloader =='refind':

                if not uefi :
                    self ._step ("grub","error")
                    self ._jsc ("pyErrorPaso",
                    self ._t ("err-refind-needs-uefi"))
                    self ._limpiar_montajes ();return

                self ._status (self ._t ("status-installing-refind"))
                self ._log (self ._t ("log-section-installing-refind"),"step")

                rc ,_ =self ._run_chroot (["pacman","-S","--noconfirm","--needed","refind"])
                if rc !=0 :
                    self ._step ("grub","error")
                    self ._jsc ("pyErrorPaso",
                    self ._t ("err-refind-pkg-failed"))
                    self ._limpiar_montajes ();return

                rc ,_ =self ._run_chroot (["refind-install"])
                if rc !=0 :
                    self ._step ("grub","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-refind-install-failed"))
                    self ._limpiar_montajes ();return

                rc_uuid ,uuid_out ,_ =_ejecutar (["blkid","-s","UUID","-o","value",dev_root ])
                root_uuid =uuid_out .strip ()if rc_uuid ==0 and uuid_out .strip ()else ""
                root_opts =(f"root=UUID={root_uuid }"if root_uuid else f"root={dev_root }")
                if not self ._modo_usb :
                    # Btrfs: sin esto el kernel monta el volumen top-level
                    # (subvolid 5) en vez del subvolumen @ real -- no
                    # arranca, cae a emergency shell. GRUB lo resuelve solo
                    # via grub-mkconfig; rEFInd/sd-boot necesitan que se lo
                    # pasemos a mano en el cmdline.
                    root_opts +=" rootflags=subvol=@"

                vmlinuz_files =glob .glob (str (MOUNT_ROOT /"boot"/"vmlinuz-*"))
                kernel_name =Path (vmlinuz_files [0 ]).name .replace ("vmlinuz-","")if vmlinuz_files else "linux"
                self ._log (self ._t ("log-kernel-detected",kernel_name =kernel_name ),"info")

                refind_conf =MOUNT_ROOT /"boot"/"refind_linux.conf"
                refind_conf .write_text (
                f'"AvalOS (normal)"   "{root_opts } rw quiet splash loglevel=3"\n'
                f'"AvalOS (verbose)"  "{root_opts } rw"\n'
                f'"AvalOS (recovery)" "{root_opts } rw single"\n'
                )
                self ._log (self ._t ("log-refind-conf-created"),"info")

                hook_dir =MOUNT_ROOT /"etc"/"pacman.d"/"hooks"
                hook_dir .mkdir (parents =True ,exist_ok =True )
                (hook_dir /"refind.hook").write_text (
                "[Trigger]\n"
                "Operation = Upgrade\n"
                "Type = Package\n"
                "Target = refind\n"
                "\n"
                "[Action]\n"
                "Description = Actualizando rEFInd en la ESP…\n"
                "When = PostTransaction\n"
                "Exec = /usr/bin/refind-install\n"
                )

                self ._step ("grub","done",self ._t ("step-refind-installed-label",kernel_name =kernel_name ))
                avanzar ()
            elif self ._bootloader =='sd-boot':

                if not uefi :
                    self ._step ("grub","error")
                    self ._jsc ("pyErrorPaso",
                    self ._t ("err-sdboot-needs-uefi"))
                    self ._limpiar_montajes ();return

                self ._status (self ._t ("status-installing-sdboot"))
                self ._log (self ._t ("log-section-installing-sdboot"),"step")

                rc ,_ =self ._run_chroot (["bootctl","install","--esp-path=/boot/efi"])
                if rc !=0 :
                    self ._step ("grub","error")
                    self ._jsc ("pyErrorPaso",self ._t ("err-bootctl-failed"))
                    self ._limpiar_montajes ();return

                vmlinuz_files =glob .glob (str (MOUNT_ROOT /"boot"/"vmlinuz-*"))
                kernel_name =Path (vmlinuz_files [0 ]).name .replace ("vmlinuz-","")if vmlinuz_files else "linux"
                self ._log (self ._t ("log-kernel-detected",kernel_name =kernel_name ),"info")

                rc_uuid ,uuid_out ,_ =_ejecutar (["blkid","-s","UUID","-o","value",dev_root ])
                root_uuid =uuid_out .strip ()if rc_uuid ==0 and uuid_out .strip ()else ""

                esp_entries_dir =MOUNT_ROOT /"boot"/"efi"/"AvalOS"
                esp_entries_dir .mkdir (parents =True ,exist_ok =True )

                _shutil =shutil
                _shutil .copy2 (MOUNT_ROOT /f"boot/vmlinuz-{kernel_name }",
                esp_entries_dir /f"vmlinuz-{kernel_name }")
                initrd_src =MOUNT_ROOT /f"boot/initramfs-{kernel_name }.img"
                if initrd_src .exists ():
                    _shutil .copy2 (initrd_src ,esp_entries_dir /f"initramfs-{kernel_name }.img")

                _ucode_copied =False
                _ucode_name =""
                if ucode :
                    _ucode_name =f"{ucode }.img"
                    _ucode_src =MOUNT_ROOT /f"boot/{_ucode_name }"
                    if _ucode_src .exists ():
                        _shutil .copy2 (_ucode_src ,esp_entries_dir /_ucode_name )
                        _ucode_copied =True
                        self ._log (self ._t ("log-microcode-copied",ucode_name =_ucode_name ),"ok")
                    else :
                        self ._log (self ._t ("log-microcode-missing",ucode_src =_ucode_src ),"warn")
                else :
                    self ._log (self ._t ("log-microcode-unidentified"),"warn")

                loader_dir =MOUNT_ROOT /"boot"/"efi"/"loader"
                loader_dir .mkdir (parents =True ,exist_ok =True )
                (loader_dir /"loader.conf").write_text (
                "default  avalos.conf\n"
                "timeout  3\n"
                "console-mode auto\n"
                "editor   no\n"
                )

                entries_dir =loader_dir /"entries"
                entries_dir .mkdir (parents =True ,exist_ok =True )
                root_opts =(f"root=UUID={root_uuid }"if root_uuid else f"root={dev_root }")
                if not self ._modo_usb :
                    root_opts +=" rootflags=subvol=@"
                _ucode_initrd_line =(
                f"initrd  /AvalOS/{_ucode_name }\n"if _ucode_copied else ""
                )
                (entries_dir /"avalos.conf").write_text (
                f"title   AvalOS\n"
                f"linux   /AvalOS/vmlinuz-{kernel_name }\n"
                f"{_ucode_initrd_line }"
                f"initrd  /AvalOS/initramfs-{kernel_name }.img\n"
                f"options {root_opts } rw quiet splash loglevel=3\n"
                )

                hook_dir =MOUNT_ROOT /"etc"/"pacman.d"/"hooks"
                hook_dir .mkdir (parents =True ,exist_ok =True )
                (hook_dir /"95-systemd-boot.hook").write_text (
                "[Trigger]\n"
                "Type = Package\n"
                f"Target = {kernel_name }\n"
                "Operation = Install\n"
                "Operation = Upgrade\n"
                "\n"
                "[Action]\n"
                "Description = Updating systemd-boot kernel files\n"
                "When = PostTransaction\n"

                f"Exec = /usr/bin/bash -c '"
                f"cp /boot/vmlinuz-{kernel_name } /boot/efi/AvalOS/vmlinuz-{kernel_name }; "
                f"cp /boot/initramfs-{kernel_name }.img /boot/efi/AvalOS/initramfs-{kernel_name }.img; "
                f"[[ -n \"{ucode }\" ]] && [[ -f /boot/{ucode }.img ]] && cp /boot/{ucode }.img /boot/efi/AvalOS/{ucode }.img || true'\n"
                "Depends = bash\n"
                )

                self ._step ("grub","done",self ._t ("step-sdboot-installed-label"))
                avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("services","active")
            self ._status (self ._t ("status-enabling-services"))

            _svc_dir =MOUNT_ROOT /"etc/systemd/system"
            _svc_dir .mkdir (parents =True ,exist_ok =True )
            (_svc_dir /"avalos-gpu-detect.service").write_text (
            "[Unit]\n"
            "Description=AvalOS — GPU Environment Detection\n"
            "Documentation=https://github.com/jeffreysama/avalos\n"
            "Before=sddm.service display-manager.service\n"
            "After=systemd-udev-settle.service\n\n"
            "[Service]\n"
            "Type=oneshot\n"
            "ExecStart=/usr/local/bin/avalos-gpu-env\n"
            "RemainAfterExit=yes\n\n"
            "[Install]\n"
            "WantedBy=graphical.target\n"
            )
            _wants =_svc_dir /"graphical.target.wants"
            _wants .mkdir (exist_ok =True )
            _symlink =_wants /"avalos-gpu-detect.service"
            if not _symlink .exists ():
                _symlink .symlink_to ("/etc/systemd/system/avalos-gpu-detect.service")
            self ._log (self ._t ("log-gpu-detect-service-ok"),"ok")

            for svc in ["NetworkManager","bluetooth","sddm","lm_sensors"]:
                self ._run_chroot (["systemctl","enable",svc ])
            self ._run_chroot (["systemctl","--global","enable",
            "pipewire","pipewire-pulse","wireplumber"])
            self ._log (self ._t ("log-sensors-detect-skipped"),"warn")

            if not self ._modo_usb :
                self ._log (self ._t ("log-section-snapper"),"step")

                rc_snap ,out_snap =self ._run_chroot (["snapper","-c","root","create-config","/"])
                if rc_snap !=0 :
                    self ._log (self ._t ("log-snapper-create-config-fail",rc =rc_snap ,out =out_snap ),"err")
                    self ._step ("services","error")
                    self ._abortado =True
                    self ._limpiar_montajes ()
                    return
                self ._log (self ._t ("log-snapper-config-created"),"ok")

                _snapper_cfg =MOUNT_ROOT /"etc"/"snapper"/"configs"/"root"
                if _snapper_cfg .exists ():
                    _cfg_txt =_snapper_cfg .read_text ()
                    _snapper_replacements ={
                    'TIMELINE_LIMIT_HOURLY="10"':'TIMELINE_LIMIT_HOURLY="5"',
                    'TIMELINE_LIMIT_DAILY="10"':'TIMELINE_LIMIT_DAILY="7"',
                    'TIMELINE_LIMIT_WEEKLY="0"':'TIMELINE_LIMIT_WEEKLY="4"',
                    'TIMELINE_LIMIT_MONTHLY="10"':'TIMELINE_LIMIT_MONTHLY="3"',
                    'TIMELINE_LIMIT_YEARLY="10"':'TIMELINE_LIMIT_YEARLY="0"',
                    'NUMBER_LIMIT="50"':'NUMBER_LIMIT="10"',
                    'NUMBER_LIMIT_IMPORTANT="50"':'NUMBER_LIMIT_IMPORTANT="10"',
                    }
                    for old ,new in _snapper_replacements .items ():
                        _cfg_txt =_cfg_txt .replace (old ,new )
                    _snapper_cfg .write_text (_cfg_txt )
                    self ._log (self ._t ("log-snapper-retention-ok"),"ok")

                for svc in ["snapper-timeline.timer","snapper-cleanup.timer"]:
                    self ._run_chroot (["systemctl","enable",svc ])
                self ._log (self ._t ("log-snapper-timers-ok"),"ok")

                if self ._bootloader =="grub":
                    self ._run_chroot (["systemctl","enable","grub-btrfsd"])

                    self ._run_chroot (["grub-mkconfig","-o","/boot/grub/grub.cfg"])
                    self ._log (self ._t ("log-grubbtrfs-ok"),"ok")
                else :
                    self ._log (self ._t ("log-grubbtrfs-skipped"),"warn")
                    self ._log (self ._t ("log-snapshots-still-work"),"warn")
                    self ._log (self ._t ("log-manual-rollback-hint"),"warn")

                _snap_dir =MOUNT_ROOT /".snapshots"
                if _snap_dir .exists ():
                    self ._run_cmd (["chmod","750",str (_snap_dir )])
                    self ._log (self ._t ("log-snapshots-perms-ok"),"ok")

                self ._log (self ._t ("log-snapshots-configured-ok"),"ok")

            self ._step ("services","done","NetworkManager · bluetooth · sddm · pipewire · snapper"
            if not self ._modo_usb else "NetworkManager · bluetooth · sddm · pipewire · avalos-gpu-detect")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._status (self ._t ("status-applying-optimizations"))
            self ._log (self ._t ("log-section-optimizations"),"step")
            self ._configurar_optimizaciones (gpu_info ,cpu_arch ,disco_tipo )

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("user","active")
            self ._status (self ._t ("status-creating-user"))
            self ._log (self ._t ("log-section-creating-user"),"step")

            rc ,_ =self ._run_chroot ([
            "useradd","-m","-G","wheel,audio,video,storage,optical",
            "-s","/bin/bash",usuario
            ])
            if rc !=0 :
                self ._step ("user","error")
                self ._jsc ("pyErrorPaso",self ._t ("err-useradd-failed",usuario =usuario ))
                self ._limpiar_montajes ();return

            rc_pw2 ,out_pw2 =self ._run_chroot_stdin (f"{usuario }:{passw }\n",["chpasswd"])
            if rc_pw2 !=0 :
                self ._log (self ._t ("log-chpasswd-user-fail",usuario =usuario ,rc =rc_pw2 ,out =out_pw2 ),"err")
                self ._limpiar_montajes ()
                return

            sudoers =MOUNT_ROOT /"etc"/"sudoers.d"/"wheel"
            sudoers .parent .mkdir (parents =True ,exist_ok =True )
            sudoers .write_text ("%wheel ALL=(ALL:ALL) ALL\n")
            sudoers .chmod (0o440 )

            self ._step ("user","done",self ._t ("step-user-created-label",usuario =usuario ))
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("aur","active")
            self ._status (self ._t ("status-installing-aur"))
            self ._log ("\n── yay + AUR ──\n","step")

            sudoers_tmp =MOUNT_ROOT /"etc"/"sudoers.d"/"99-aur-build"
            try :
                sudoers_tmp .write_text (f"{usuario } ALL=(ALL:ALL) NOPASSWD: ALL\n")
            except OSError :
                sudoers_tmp =None

            yay_script =(
            "set -euo pipefail; "
            "TMPD=$(mktemp -d) && "
            "git clone --depth=1 https://aur.archlinux.org/yay.git \"$TMPD/yay_build\" && "
            "cd \"$TMPD/yay_build\" && "
            "makepkg -si --noconfirm --needed && "
            "rm -rf \"$TMPD\""
            )
            rc ,_ =self ._run_chroot (
            ["sudo","-H","-u",usuario ,"bash","-c",yay_script ],timeout =600
            )
            if rc !=0 :
                self ._log (self ._t ("log-yay-not-installed"),"warn")
                self ._step ("aur","skip",self ._t ("step-yay-failed-label"))
            else :
                all_aur =HYPRLAND_AUR_PKGS +(GAMING_AUR_PKGS if self ._install_gaming else [])
                if all_aur :
                    rc_aur ,_ =self ._run_chroot (
                    ["sudo","-H","-u",usuario ,"yay","-S","--noconfirm","--needed"]
                    +all_aur ,timeout =1800
                    )
                    if rc_aur !=0 :
                        self ._log (
                        self ._t ("log-aur-partial-fail",rc =rc_aur ),
                        "warn"
                        )
                        self ._step ("aur","done",self ._t ("step-aur-count-warn",n =len (all_aur )))
                    else :
                        self ._step ("aur","done",self ._t ("step-aur-count",n =len (all_aur )))
                else :
                    self ._step ("aur","done",self ._t ("step-aur-count-zero"))

                if self ._install_gaming :

                    self ._run_chroot (["usermod","-aG","gamemode",usuario ])

                    gamemode_conf =(
                    "[general]\n"
                    "reaper_freq=5\n"
                    "defaultgov=performance\n"
                    "desiredgov=performance\n"
                    "softrealtime=auto\n"
                    "renice=-10\n\n"
                    "[gpu]\n"
                    "apply_gpu_optimisations=accept-responsibility\n"
                    "gpu_device=0\n"
                    "amd_performance_level=high\n\n"
                    "[filter]\n"
                    "whitelist=steam\nwhitelist=lutris\nwhitelist=heroic\n"
                    )
                    try :
                        gm_path =MOUNT_ROOT /"etc"/"gamemode.ini"
                        gm_path .write_text (gamemode_conf ,encoding ="utf-8")
                        self ._log (self ._t ("log-gamemode-ini-ok"),"ok")
                    except OSError as e :
                        self ._log (f"[WARN] gamemode.ini: {e }","warn")

                    _contenido_mango =_leer_config ("mangohud/MangoHud.conf")
                    if _contenido_mango :
                        mango_dir =MOUNT_ROOT /"etc"/"MangoHud"
                        mango_dir .mkdir (parents =True ,exist_ok =True )
                        (mango_dir /"MangoHud.conf").write_text (_contenido_mango ,encoding ="utf-8")
                        self ._log (self ._t ("log-mangohud-ok"),"ok")

                    self ._run_chroot (
                    ["sudo","-H","-u",usuario ,"flatpak","remote-add",
                    "--if-not-exists","flathub",
                    "https://dl.flathub.org/repo/flathub.flatpakrepo"],
                    timeout =120
                    )
                    self ._log (self ._t ("log-flathub-ok"),"ok")

            if sudoers_tmp and sudoers_tmp .exists ():
                try :sudoers_tmp .unlink ()
                except OSError :pass

            avanzar ()

            self ._step ("hypr","active")
            self ._status (self ._t ("status-configuring-hyprland"))
            self ._label (self ._t ("label-configuring-hyprland"))
            self ._log (self ._t ("log-section-hyprland-config"),"step")
            self ._configurar_hyprland (usuario ,gpu_info )
            self ._step ("hypr","done","SDDM · Waybar · hyprland.lua · rofi · kitty")
            avanzar ()

            if self ._abortado :self ._limpiar_montajes ();return

            self ._step ("umount","active")
            self ._status (self ._t ("status-unmounting"))
            self ._log (self ._t ("log-section-unmounting"),"step")
            self ._limpiar_montajes ()
            self ._step ("umount","done")
            avanzar ()

            done_info =(
            f"<strong>Disco:</strong> {dev } ({disco ['size_human']})<br>"
            f"<strong>Usuario:</strong> {usuario }<br>"
            f"<strong>Hostname:</strong> {hostname }<br>"
            f"<strong>Timezone:</strong> {timezone }<br>"
            f"<strong>Modo:</strong> {'USB (ext4 noatime)'if self ._modo_usb else 'Disco (Btrfs)'}<br>"
            f"<strong>Bootloader:</strong> { {'grub':'GRUB','sd-boot':'systemd-boot','refind':'rEFInd','none':'Omitido'}.get (self ._bootloader ,'?')}<br>"
            f"<strong>DE/WM:</strong> Hyprland · Wayland · SDDM<br>"
            f"<strong>✓ Contraseña:</strong> establecida correctamente"
            )
            self ._jsc ("pyInstalacionCompleta",done_info )
            self ._label (self ._t ("label-done"))
            self ._log (
            self ._t ("log-final-banner",dev =dev ,size_human =disco ["size_human"],usuario =usuario ,hostname =hostname ,timezone =timezone ),"ok"
            )

        except Exception as e :
            import traceback
            self ._log (self ._t ("log-fatal-exception",e =e ,tb =traceback .format_exc ()),"err")
            self ._jsc ("pyErrorPaso",self ._t ("err-unexpected",e =e ))
            self ._limpiar_montajes ()
        finally :
            self ._instalando =False

            _sudoers_guard =MOUNT_ROOT /"etc"/"sudoers.d"/"99-aur-build"
            if _sudoers_guard .exists ():
                try :
                    _sudoers_guard .unlink ()
                    self ._log (self ._t ("log-cleanup-sudoers-ok"),"ok")
                except OSError as _e :
                    self ._log (self ._t ("log-cleanup-sudoers-fail",e =_e ),"warn")
            self ._jsc ("pyStopTimer")

def _build_html ()->str :

    tz_json =json .dumps (TIMEZONES ,ensure_ascii =False )
    default_tz =json .dumps (DEFAULT_TIMEZONE )
    default_host =json .dumps (DEFAULT_HOSTNAME )
    locales_json =json .dumps (LOCALES ,ensure_ascii =False )
    keymaps_json =json .dumps (KEYMAPS ,ensure_ascii =False )
    default_loc =json .dumps (DEFAULT_LOCALE )
    default_km =json .dumps (DEFAULT_KEYMAP )

    strings_json =json .dumps (translations .TRANSLATIONS ,ensure_ascii =False )

    inject =(
    f"window._tzList = {tz_json };\n"
    f"window._defaultTZ = {default_tz };\n"
    f"window._defaultHostname = {default_host };\n"
    f"window._localeList = {locales_json };\n"
    f"window._keymapList = {keymaps_json };\n"
    f"window._defaultLocale = {default_loc };\n"
    f"window._defaultKeymap = {default_km };\n"
    )

    contenido =_HTML .replace ("LOGO_PLACEHOLDER",_LOGO_B64 )
    contenido =contenido .replace ("STRINGS_PLACEHOLDER",strings_json )
    # FIX: el punto de inyección anterior era justo antes del listener
    # 'pywebviewready' (casi al final del <script>). Pero initTZ()/initLocale()/
    # initKeymap() son IIFEs que se auto-ejecutan MUCHO antes en el mismo
    # script (apenas se declaran, no esperan a pywebviewready), y esas IIFEs
    # son las que leen window._tzList/_localeList/_keymapList. Con el punto
    # de inyección viejo, esas variables todavía no existían cuando las IIFEs
    # corrían -> "Cannot read properties of undefined (reading 'forEach')" ->
    # esa excepción sin capturar abortaba TODO el resto del script, incluyendo
    # "const PASOS = [...]" más abajo -> los botones de idioma llamaban a
    # chooseLang()/applyLang(), que a su vez tocaban PASOS todavía no
    # inicializado -> "Cannot access 'PASOS' before initialization" -> el
    # click no hacía nada, en los 3 idiomas por igual (confirmado simulando
    # el DOM completo). Fix: inyectar las variables inmediatamente después de
    # 'use strict';, ANTES de cualquier IIFE que las consuma.
    return contenido .replace (
    "'use strict';",
    "'use strict';\n"+inject
    )

if __name__ =="__main__":

    if os .geteuid ()!=0 :
        print ("╔═══════════════════════════════════════════════════╗")
        print ("║  AvalOS Installer necesita privilegios de root.   ║")
        print ("╠═══════════════════════════════════════════════════╣")
        print ("║  Ejecuta con:  sudo python avalos-install         ║")
        print ("║  O como root:  python avalos-install              ║")
        print ("╚═══════════════════════════════════════════════════╝")
        sys .exit (1 )

    os .environ ["WEBKIT_DISABLE_SANDBOX_THIS_IS_DANGEROUS"]="1"
    os .environ ["WEBKIT_DISABLE_COMPOSITING_MODE"]="1"
    os .environ ["WEBKIT_DISABLE_DMABUF_RENDERER"]="1"

    vent =VentanaInstalador ()
    api =InstaladorAPI (vent )

    html =_build_html ()

    try :
        from gi .repository import GLib
        GLib .set_prgname ("avalos-install")
    except Exception :
        pass

    win =webview .create_window (
    title ="AvalOS — Instalador",
    html =html ,
    js_api =api ,
    width =960 ,
    height =640 ,
    min_size =(800 ,540 ),
    resizable =True ,
    background_color ="#1a1b26",
    )
    vent .window =win
    win .events .closed +=vent ._on_close

    def _on_loaded ():

        with vent ._lock :
            if vent ._thread_started :
                return
            vent ._thread_started =True
            vent ._config_lista .clear ()
        t =threading .Thread (target =vent ._run_instalacion ,daemon =True )
        t .start ()

    win .events .loaded +=_on_loaded

    try :
        webview .start (debug =os .environ .get ("AVALOS_DEBUG")=="1")
    except Exception as e :
        print (f"ERROR al iniciar pywebview: {e }")
        print ("Asegúrate de que webkit2gtk-4.1 esté instalado:")
        print ("  pacman -S webkit2gtk-4.1 python-gobject")
        sys .exit (1 )
